for _s in (sys.stdout, sys.stderr):
    try:
        _s.reconfigure(encoding="utf-8")
    except Exception:
        pass


def _pip_install(*packages: str) -> bool:
    if not packages:
        return True
    cmd = [sys.executable, "-m", "pip", "install", "-q", "--prefer-binary", *packages]
    print(f"[*] نصب: {' '.join(packages)}")
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=900)
        if r.returncode != 0:
            err = (r.stderr or r.stdout or "")[-800:]
            print(f"    [!] ناموفق: {err}")
            return False
        return True
    except Exception as e:
        print(f"    [!] خطا: {e}")
        return False


def _pip_uninstall(*packages: str) -> None:
    try:
        subprocess.run(
            [sys.executable, "-m", "pip", "uninstall", "-y", *packages],
            capture_output=True,
            timeout=180,
        )
    except Exception:
        pass


def _can_import(module: str) -> bool:
    try:
        __import__(module)
        return True
    except Exception:
        return False


def _nvidia_gpu_present() -> bool:
    try:
        import torch
        if torch.cuda.is_available():
            return True
    except Exception:
        pass
    try:
        r = subprocess.run(["nvidia-smi", "-L"], capture_output=True, timeout=8)
        if r.returncode == 0 and b"GPU" in (r.stdout or b""):
            return True
    except Exception:
        pass
    try:
        if os.path.exists("/dev/nvidia0") or os.path.exists("/dev/nvidiactl"):
            return True
    except Exception:
        return False
    return False


