def _ensure_all_dependencies() -> None:
    if _IS_ANDROID:
        print("[*] اندروید: وابستگی‌ها داخل APK موجود است — بررسی pip رد شد.")
        return
    print("[*] بررسی وابستگی‌ها ...")
    core = []
