_GPU_VENDOR_CACHE = None


def _gpu_vendor() -> str:
    """v1.14.117 — تشخیصِ فروشندهٔ GPU رویِ اندروید: "adreno" / "mali" /
    "powervr" / "unknown" (رویِ PC همیشه "unknown" و بدونِ هیچ اثری).
    با getprop (ro.hardware.egl / ro.soc.model / ro.board.platform).
    زمینه: کرنلهایِ OpenCLِ مدلهایِ nb موقعِ ساختِ predictor رویِ
    درایورهایِ Mali JIT میشوند و رویِ بعضی درایورها سگفلتِ native
    میدهند (کرشِ 2026-10-28، Redmi 22021211RG / هلیو G96 / Mali-G57)
    — رویِ Adreno سالهاست ثابت است."""
    global _GPU_VENDOR_CACHE
    if _GPU_VENDOR_CACHE is not None:
        return _GPU_VENDOR_CACHE
    v = "unknown"
    try:
        if _on_android():
            import re as _re
            import subprocess as _sp
            props = []
            for key in ("ro.hardware.egl", "ro.hardware",
                        "ro.board.platform", "ro.soc.manufacturer",
                        "ro.soc.model"):
                try:
                    props.append(str(_sp.check_output(
                        ["getprop", key], timeout=5,
                        stderr=_sp.DEVNULL).decode("utf-8", "replace").strip()))
                except Exception:
                    props.append("")
            _egl = props[0].lower()
            if "adreno" in _egl:
                v = "adreno"
            elif "mali" in _egl:
                v = "mali"
            elif "powervr" in _egl:
                v = "powervr"
            if v == "unknown":
                blob = " ".join(props).lower()
                if (any(t in blob for t in ("adreno", "qcom", "qualcomm"))
                        or _re.search(r"\b(sm|sdm|qcs)[0-9]", blob)):
                    v = "adreno"
                elif ("mali" in blob or "mediatek" in blob
                        or "helio" in blob or "dimens" in blob
                        or _re.search(r"\bmt[0-9]", blob)):
                    v = "mali"
                elif "powervr" in blob or "imgtec" in blob:
                    v = "powervr"
    except Exception:
        pass
    _GPU_VENDOR_CACHE = v
    return v


def _cpu_ep_xnnpack() -> bool:
    """v1.14.96-speed (SRV-G) — A/Bِ XNNPACK: فقط با env
    MANGA_CPU_EP=xnnpack (پیش‌فرض: خاموش). سشن‌هایِ CPU-EP به‌جای
    CPU-Only از ["XnnpackExecutionProvider","CPUExecutionProvider"]
    می‌روند با کانفیگِ رسمی: ORT intra=1 + XNNPACK intra=هسته‌هایِ
    فیزیکی + spinning خاموش. رویِ اندروید/امولاتور اعمال نمی‌شود تا
    مسیرِ گوشی دست‌نخورده بماند."""
    try:
        if (os.environ.get("MANGA_CPU_EP", "").strip().lower()
                != "xnnpack"):
            return False
    except Exception:
        return False
    try:
        if _on_android() or _android_like_env():
            return False
    except Exception:
        pass
    return True


def _physical_core_count() -> int:
    """v1.14.96-speed (SRV-G) — هسته‌هایِ فیزیکی (برایِ XNNPACK
    threadpool). fallback: os.cpu_count()."""
    try:
        _phys = set()
        _pid = _cid = None
        with open("/proc/cpuinfo", "r", encoding="ascii", errors="ignore") as _f:
            for _ln in _f:
                _ln = _ln.strip()
                if _ln.startswith("physical id"):
                    _pid = _ln.split(":", 1)[1].strip()
                elif _ln.startswith("core id"):
                    _cid = _ln.split(":", 1)[1].strip()
                elif _ln.startswith("processor") and _ln.endswith(":") is False:
                    pass
                if _ln == "" and _pid is not None and _cid is not None:
                    _phys.add((_pid, _cid))
                    _pid = _cid = None
        if _phys:
            return max(1, len(_phys))
    except Exception:
        pass
    try:
        return max(1, os.cpu_count() or 1)
    except Exception:
        return 1


def _ort_session_options(threads: int = 4, low_mem: Optional[bool] = None,
                         prefer_gpu: Optional[bool] = None):
    so = ort.SessionOptions()
    so.log_severity_level = 3
    so.graph_optimization_level = ort.GraphOptimizationLevel.ORT_ENABLE_ALL
    # v1.14.96-speed — فیکسِ باگِ تک‌نخیِ x86_64: محدودیتِ «نخ=۱» فقط برایِ
    # اندروید بود (ORT-androidِ x86_64 در زمان‌بندِ thread-pool تقسیم‌برِصفر
    # /SIGFPE می‌دهد) ولی چون فقط machine را چک می‌کرد، رویِ «همهٔ»
    # میزبان‌هایِ x86_64 (PC/سرورِ لینوکس/ویندوز) هم اعمال می‌شد → LaMa/
    # دیتکتور/OCR رویِ PC تک‌نخ می‌شدند و چند برابر کند بودند. حالا فقط
    # وقتی فعال است که واقعاً اندروید باشیم (Chaquopy یا نشانه‌هایِ محیطِ
    # اندروید مثل /system/build.prop یا ANDROID_ROOT) و معماری x86_64
    # (یعنی امولاتور).
    # v1.14.99 (SRV-H4) — بازگشتِ دقیق به معنایِ e32bccf: مقدارِ «پاس‌شده»
    # (پیش‌فرضِ ۴) رویِ همهٔ میزبان‌هایِ غیرِ امولاتور استفاده می‌شود؛
    # «۰ = ORT auto»یِ SRV-G رویِ سرور کندتر بود (SRV-H2: +30..+67٪ CPU)
    # و حذف شد. امولاتورِ x86_64 همان قراردادِ SRV-F (intra=1).
    # MANGA_ORT_THREADS=N همچنان اوررایدِ صریح دارد (اولاً بعد از cap1).
    _cap1_67 = _android_x86_emulator()
    _xnn67 = _cpu_ep_xnnpack()
    try:
        _env_t67 = int(os.environ.get("MANGA_ORT_THREADS", "0") or 0)
    except Exception:
        _env_t67 = 0
    if _cap1_67:
        threads = 1
    elif _env_t67 > 0:
        threads = _env_t67
    elif _xnn67:
        # کانفیگِ رسمیِ XNNPACK (فقط MANGA_CPU_EP=xnnpack): threadpoolِ ORT
        # تک‌نخی؛ XNNPACK خودش threadpoolِ هسته‌هایِ فیزیکی را می‌سازد.
        threads = 1
    else:
        # v1.14.99-speed (SRV-L) — هیوریستیکِ میزبان به‌جایِ مقدارِ ثابتِ
        # «پاس‌شده»: رویِ PC/سرورِ واقعیِ x86_64 با ≥۸ هسته، برندهٔ سوییپِ
        # SRV-K (t8: CPU ۳۲.۲s / GPU ۱۸.۷s) پیش‌فرضِ fastest-mode می‌شود؛
        # رویِ میزبانِ ضعیف/کم‌هسته همان مقدارِ پاس‌شده (۴) می‌ماند.
        # MANGA_ORT_THREADS همچنان اوررایدِ مطلق است (فقط cap1 امولاتور
        # از آن بالاتر است).
        # انحرافِ مستندشده از اسپک (SRV-L): رشتهٔ «gvisor» در
        # uname.release دیگر سقفِ ۴ را رویِ میزبانِ بزرگ اعمال نمی‌کند —
        # سرورِ ۲۰ هسته‌ایِ Azure هم «4.19.0-gvisor» گزارش می‌کند (SRV-K
        # آن را با AVX512 «بدونِ gVisor» تشخیص داده بود) و سوییپِ خودِ
        # همان میزبان t8 را برنده داد؛ در داده‌هایِ میزبانِ قبلیِ gVisor
        # هم CPU با ۸ نخ بهتر بود (SRV-H3: c8nb 34.8s در برابرِ c4nb
        # 39.0s). گاردِ میزبانِ ضعیف، شرطِ «≥۸ هسته» است (میزبان‌هایِ
        # gVisorِ کوچک/CI → همان ۴).
        try:
            import platform as _pfl
            _m_l = _pfl.machine().lower() in ("x86_64", "amd64")
            _gv_l = "gvisor" in (os.uname().release.lower()
                                 if hasattr(os, "uname") else "")
            if _m_l and (os.cpu_count() or 4) >= 8:
                threads = 8
            elif _gv_l:
                threads = 4  # میزبانِ gVisorِ کوچک → صریحاً ۴
            # else: همان threadsِ پاس‌شده — بدونِ auto
        except Exception:
            pass
    try:
        _t67 = int(threads)
    except Exception:
        _t67 = 4
    # v1.14.99-speed (SRV-L) — گاردِ SIGABRTِ مسیرِ CUDA: با نخِ ۲۰ رویِ
    # سشن‌هایِ CUDA/TRT، per-patchِ LaMa رویِ سرورِ تازه ORT را با
    # SIGABRT (exit=134) می‌کشد (SRV-K g20). سقفِ سختِ ۱۶ فقط وقتی
    # سشنِ GPU خواسته شده؛ مسیرِ CPU دست‌نخورده می‌ماند.
    try:
        if prefer_gpu and _t67 > 16:
            _t67 = 16
    except Exception:
        pass
    so.intra_op_num_threads = _t67 if _t67 > 0 else 0
    so.inter_op_num_threads = 1
    so.execution_mode = ort.ExecutionMode.ORT_SEQUENTIAL
    # پچ‌های موازی LaMa + OCR هم‌زمان اجرا می‌شوند؛ spin-wait هسته‌ها را می‌سوزاند
    # v1.14.67 — رویِ x86_64 این کانفیگ SIGFPE می‌دهد (حدس: شمارشِ spin=۰
    # → تقسیم بر صفر در مسیرِ x86) — فقط رویِ arm خاموش می‌شود
    if not _on_x86():
        try:
            so.add_session_config_entry(
                "session.intra_op.allow_spinning", "0")
        except Exception:
            pass
    # v1.14.96-speed (SRV-G phase2) — tuningِ spin برایِ threadpoolِ CPU
    # چندنخی (کمبوِ رسمیِ مستنداتِ threadingِ onnxruntime):
    #   spin_duration_us=1000 + spin_backoff_max=8
    # v1.14.99 (SRV-H4) — پیش‌فرضِ خاموش (رویِ میزبانِ gVisor کندتر بود؛
    # SRV-H2)؛ فقط با MANGA_SPIN=1 و وقتی pool چندنخی است (۰ یا >۱)،
    # رویِ میزبانِ غیرِ اندروید و خارج از XNNPACK فعال می‌شود.
    try:
        _spin_h4 = str(os.environ.get("MANGA_SPIN", "")).strip() == "1"
    except Exception:
        _spin_h4 = False
    if _spin_h4 and (not _cap1_67) and (not _xnn67) \
            and (not _android_like_env()) and (_t67 == 0 or _t67 > 1):
        try:
            so.add_session_config_entry(
                "session.intra_op.spin_duration_us", "1000")
            so.add_session_config_entry(
                "session.intra_op.spin_backoff_max", "8")
        except Exception:
            pass
    if _xnn67:
        # کانفیگِ رسمیِ XNNPACK: spinning خاموش (نخِ ORT فقط هماهنگ می‌کند)
        try:
            so.add_session_config_entry(
                "session.intra_op.allow_spinning", "0")
        except Exception:
            pass
    if low_mem is None:
        _av = _sys_avail_ram_gb()
        # v1.14.105 — MANGA_LOW_MEM=1: اجبارِ حالتِ کم‌رم (آرنا/الگوی
        # حافظه خاموش) — برایِ دستگاه‌هایِ ۴GB و نوارهایِ بلندِ وبتون که
        # به مرزِ OOM می‌رسند
        low_mem = bool(_on_android()
                       or (_av is not None and _av < 3.0)
                       or os.environ.get("MANGA_LOW_MEM", "") == "1")
    so.enable_cpu_mem_arena = (not low_mem)
    so.enable_mem_pattern = (not low_mem)
    return so


def _trt_ep_usable() -> bool:
    """v1.14.96-speed — TensorrtExecutionProvider فقط وقتی «واقعاً» قابلِ
    استفاده است. حضورش در get_available_providers کافی نیست؛ بدونِ
    کتابخانهٔ nvinfer ساختِ سشن یا شکست می‌خورد یا برایِ ساختِ engine
    گیر می‌کند → ماژولِ tensorrt لازم است یا اجباری با MANGA_ALLOW_TRT=1
    (و انکار با MANGA_NO_TRT=1)."""
    try:
        if os.environ.get("MANGA_NO_TRT", "").strip() == "1":
            return False
    except Exception:
        pass
    try:
        import tensorrt  # noqa: F401
        return True
    except Exception:
        pass
    try:
        return os.environ.get("MANGA_ALLOW_TRT", "").strip() == "1"
    except Exception:
        return False


def _best_providers_for(kind: str = "generic", prefer_gpu: bool = True):
    """v1.14.96-speed — انتخابگرِ مرکزیِ EP از آنچه واقعاً نصب/موجود است.

    خروجی: لیستِ مرتبِ providers برایِ ort.InferenceSession — سریع‌ترین
    EPِ موجود اول و همیشه CPU آخرِ لیست. اولویتِ GPU: TensorRT (فقط
    usable) → CUDA → ROCm → MIGraphX → Dml (ویندوز) → QNN/NNAPI
    (اندروید) → CoreML (مک). در حالتِ --cpu فقط CPU (اگر OpenVINOِ واقعی
    نصب باشد جلوتر می‌آید؛ «Azure» ضمیمهٔ همهٔ بیلدهایِ معمولی ORT است و
    EPِ شتاب‌دهندهٔ لوکال نیست → هرگز جلو نمی‌آید). انتخابِ EP خروجیِ
    مدل‌ها را عوض نمی‌کند — فقط سرعتِ اجرا."""
    try:
        avail = list(ort.get_available_providers())
    except Exception:
        avail = []
    out = []
    if prefer_gpu:
        for _ep in ("TensorrtExecutionProvider", "CUDAExecutionProvider",
                    "ROCmExecutionProvider", "MIGraphXExecutionProvider",
                    "DmlExecutionProvider"):
            if _ep not in avail:
                continue
            if _ep == "TensorrtExecutionProvider" and not _trt_ep_usable():
                continue
            out.append(_ep)
        try:
            if _on_android() or _android_like_env():
                for _ep in ("QNNExecutionProvider", "NNAPIExecutionProvider"):
                    if _ep in avail:
                        out.append(_ep)
            elif sys.platform == "darwin" \
                    and "CoreMLExecutionProvider" in avail:
                out.append("CoreMLExecutionProvider")
        except Exception:
            pass
    else:
        # --cpu: x86_64 → فقط CPU (همان EPِ همیشگی، نتیجهٔ بیت‌به‌بیت یکسان)
        if "OpenVINOExecutionProvider" in avail:
            out.append("OpenVINOExecutionProvider")
        # v1.14.96-speed (SRV-G) — A/Bِ XNNPACK (فقط MANGA_CPU_EP=xnnpack):
        # سشن‌هایِ CPU-EP از XNNPACK+CPU می‌روند با کانفیگِ رسمی
        # (ORT intra=1 + XNNPACK intra=فیزیکی + spin خاموش) — پیش‌فرضِ خاموش.
        if _cpu_ep_xnnpack() and "XnnpackExecutionProvider" in avail:
            out.append("XnnpackExecutionProvider")
    # امولاتورِ اندرویدِ x86_64: CPU-EPِ ORT-android می‌میرد (SIGFPE)
    # → XNNPACK اجباری (همان رفتارِ v1.14.67)
    if _on_x86() and "XnnpackExecutionProvider" in avail:
        out.append("XnnpackExecutionProvider")
    out.append("CPUExecutionProvider")
    _seen, _res = set(), []
    for _p in out:
        if _p not in _seen:
            _seen.add(_p)
            _res.append(_p)
    return _res or ["CPUExecutionProvider"]


def _cudnn_algo_search() -> Optional[str]:
    """v1.14.99 (SRV-H4) — الگوریتمِ جست‌وجویِ cudnn برایِ convها.

    پیش‌فرضِ «HEURISTIC» برایِ «همهٔ» سشن‌هایِ CUDA — تنها بردِ اثبات‌
    شدهٔ speed2 رویِ GPU (SRV-H3: 01.jpg GPU بدونِ batch = 21.3s در
    برابرِ 23.3s بیس‌لاین). جست‌وجویِ EXHAUSTIVEِ پیش‌فرضِ ORT برایِ هر
    شکلِ تازه رویِ میزبانِ gVisor صدها میلی‌ثانیه می‌گیرد؛ HEURISTIC آن
    را حذف می‌کند. opt-out: MANGA_CUDNN_ALGO=exhaustive (یا off/none/0)
    → None → رفتارِ قدیمیِ EXHAUSTIVE دست‌نخورده."""
    try:
        _v_h4 = os.environ.get("MANGA_CUDNN_ALGO", "").strip().lower()
        if _v_h4 in ("exhaustive", "off", "none", "0"):
            return None
    except Exception:
        pass
    return "HEURISTIC"


def _build_provider_options(providers):
    """v1.14.96-speed (SRV-G phase2) — provider options برایِ سشن‌هایِ GPU:
    CUDA → {"cudnn_conv_use_max_workspace": "1"} (صریح؛ پیش‌فرضِ ORT هم 1
    است ولی این‌طور به آن اعتماد نمی‌کنیم). cudnn_conv_algo_search دست
    نمی‌خورد (EXHAUSTIVE می‌ماند) و CUDA graphs روشن نمی‌شود (شکل‌هایِ
    داینامیک). XNNPACK (فقط MANGA_CPU_EP=xnnpack) → intra_op_num_threads =
    هسته‌هایِ فیزیکی (کانفیگِ رسمی). خروجی None رویِ لیستِ بدونِ CUDA/XNNPACK
    → دقیقاً رفتارِ قبلی (سشنِ CPU خالص).
    v1.14.99 (SRV-H4) — کلیدِ «cudnn_conv_algo_search»: "HEURISTIC"
    پیش‌فرض است (MANGA_CUDNN_ALGO=exhaustive حذفش می‌کند) — تکِ نقطهٔ
    مونتاژِ optionsِ CUDA برایِ همهٔ سشن‌ها از همین تابع می‌گذرد."""
    try:
        if not providers:
            return None
        _gpu_cuda = "CUDAExecutionProvider" in providers
        _xnn = _cpu_ep_xnnpack() and "XnnpackExecutionProvider" in providers
        if not (_gpu_cuda or _xnn):
            return None
        _opts = [{} for _ in providers]
        for _i, _p in enumerate(providers):
            if _p == "CUDAExecutionProvider":
                _opts[_i] = {"cudnn_conv_use_max_workspace": "1"}
                # v1.14.99 (SRV-H4) — HEURISTIC پیش‌فرض (حذفِ re-searchِ
                # EXHAUSTIVE برایِ هر شکلِ تازه)؛ MANGA_CUDNN_ALGO=exhaustive
                # → None → بدونِ این کلید (رفتارِ قدیمی).
                _algo_h4 = _cudnn_algo_search()
                if _algo_h4:
                    _opts[_i]["cudnn_conv_algo_search"] = _algo_h4
            elif _p == "XnnpackExecutionProvider":
                try:
                    _opts[_i] = {"intra_op_num_threads":
                                 str(max(1, int(_physical_core_count())))}
                except Exception:
                    _opts[_i] = {}
        return _opts
    except Exception:
        return None


# ── v1.14.69 — کشِ «مدلِ بهینه‌شده» برایِ LaMa ──────────────────────────
# لاگِ POCO F4 (1.14.68): [TIME] lama-wait=67.3s → کلِ زمان در
# OrtEnvironment.createSession رویِ مدلِ ۲۰۶MB می‌رود؛ بهینه‌سازِ گرافِ
# ORT تک‌نخی است و رویِ هسته‌هایِ ضعیف + رمِ آزادِ ~۳۵۵MB ده‌ها ثانیه
# طول می‌کشد (رویِ PC/امولاتور <۱s — برایِ همین دیده نمی‌شد).
# راه: بارِ اول، مدلِ بهینه‌شده رویِ دیسک ذخیره می‌شود
# (SessionOptions.optimized_model_filepath — در pip هست؛ در شیمِ اندروید
# به OrtSession.SessionOptions.setOptimizationModelFilePath جاوا
# می‌رود) و بارهایِ بعدی از همان فایل ساخته می‌شوند → مرحلهٔ
# بهینه‌سازی کامل حذف می‌شود. ذخیره با EPِ CPU انجام می‌شود (الگوی
# استاندارد؛ مدلِ بهینه‌شده، گرافِ عمومیِ بهینه است) و بارگذاری با
# هر EPِ درخواستی خودش دوباره EP را سوار می‌کند.
_LAMA_OPT_LOCK = threading.Lock()


def _lama_opt_cache_path(model_path: str, providers) -> str:
    _v = "x"
    try:
        _v = str(getattr(ort, "__version__", "x") or "x")
    except Exception:
        pass
    _ep = "cpu"
    try:
        for _p in (providers or ()):
            if str(_p).lower().startswith("xnnpack"):
                _ep = "xnnpack"
                break
    except Exception:
        pass
    _d, _f = os.path.split(str(model_path))
    _stem = _f[:-5] if _f.lower().endswith(".onnx") else _f
    return os.path.join(_d, f"{_stem}.opt69-{_v}-{_ep}.onnx")


def _lama_session_cached(model_path, so, providers, provider_options=None):
    """سشنِ LaMa با کشِ مدلِ بهینه‌شده + [TIME]ِ زمانِ ساخت.

    شکستِ هر مرحله = رفتارِ قبل (بدونِ کش) — هیچ مسیرِ تازه‌ای نباید
    بتواند ساختِ سشن را خراب کند.
    v1.14.96-speed (SRV-G): provider_options اختیاری است (CUDA EP:
    cudnn_conv_use_max_workspace=1). None = دقیقاً رفتارِ قبل."""
    _t69 = time.time()
    _opt69 = None
    try:
        if str(os.environ.get("MANGA_LAMA_OPT_CACHE", "1")).strip() == "1" \
                and isinstance(model_path, str):
            _opt69 = _lama_opt_cache_path(model_path, providers)
    except Exception:
        _opt69 = None
    if _opt69 and os.path.isfile(_opt69) \
            and os.path.getsize(_opt69) > 1_000_000:
        try:
            _s69 = ort.InferenceSession(_opt69, sess_options=so,
                                        providers=providers,
                                        provider_options=provider_options)
            try:
                print(f"[TIME] lama-create={time.time() - _t69:.1f}s "
                      f"(از کشِ بهینه‌شده)", flush=True)
            except Exception:
                pass
            return _s69
        except Exception:
            try:
                os.remove(_opt69)
            except Exception:
                pass
    # بارِ اول: مدلِ بهینه‌شده ذخیره می‌شود (اگر ORT پشتیبانی نکرد،
    # بی‌صدا مثلِ قبل). رویِ اندروید سطحِ بهینه‌سازی BASIC — بهینه‌سازِ
    # ALLِ تک‌نخی بخشِ بزرگی از همان ۶۷s است و XNNPACKِ سنگین‌کارِ
    # اصلی را خودش انجام می‌دهد (رویِ PC: ALL→BASIC فقط ‎+۴٪ زمانِ
    # اجرا؛ ساخت ×۲.۵ سریع‌تر).
    _part69 = None
    try:
        _android69 = _on_android()
    except Exception:
        _android69 = False
    if _opt69 and _android69:
        try:
            so.graph_optimization_level = \
                ort.GraphOptimizationLevel.ORT_ENABLE_BASIC
        except Exception:
            pass
    if _opt69:
        _part69 = _opt69 + ".part"
        try:
            so.optimized_model_filepath = _part69
        except Exception:
            _part69 = None
    try:
        _s69 = ort.InferenceSession(model_path, sess_options=so,
                                    providers=providers,
                                    provider_options=provider_options)
    finally:
        try:
            if _part69 and os.path.isfile(_part69):
                with _LAMA_OPT_LOCK:
                    try:
                        os.replace(_part69, _opt69)
                        try:
                            print(f"[TIME] lama-create={time.time() - _t69:.1f}s "
                                  f"(مدلِ بهینه‌شده ذخیره شد → کش)", flush=True)
                        except Exception:
                            pass
                    except Exception:
                        try:
                            os.remove(_part69)
                        except Exception:
                            pass
        except Exception:
            pass
    try:
        print(f"[TIME] lama-create={time.time() - _t69:.1f}s", flush=True)
    except Exception:
        pass
    return _s69


_ORT_CUDA_OK = None


def _prepare_ort_cuda_dlls() -> None:
    try:
        import torch
        if torch.cuda.is_available():
            try:
                _ = torch.empty(1, device="cuda")
            except Exception:
                pass
    except Exception:
        pass
    try:
        if hasattr(ort, "preload_dlls"):
            try:
                ort.preload_dlls(cuda=True, cudnn=True, msvc=True, directory="")
            except TypeError:
                ort.preload_dlls()
            except Exception:
                try:
                    ort.preload_dlls()
                except Exception:
                    pass
    except Exception:
        pass


def _on_x86() -> bool:
    """v1.14.67 — فقط «امولاتورِ x86_64» (اندروید + x86): CPU-EPِ
    libonnxruntimeِ x86_64 در sess.run تقسیم‌برصفر (SIGFPE) می‌دهد؛
    XNNPACK سالم است. PCِ لینوکسی x86 هم هست ولی اندروید نیست → False
    (وگرنه نخِ PC به ۱ محدود و مسیرِ XNNPACK خراب می‌شد)."""
    try:
        if not _on_android():
            return False
        import platform as _pf
        return _pf.machine().lower() in ("x86_64", "amd64")
    except Exception:
        return False


def _is_auto_ep() -> bool:
    try:
        v = (os.environ.get("MANGA_ORT_EP", "auto") or "auto").strip().lower()
    except Exception:
        return True
    return v in ("", "auto")


def _resolve_lama_ep():
    try:
        v = (os.environ.get("MANGA_ORT_EP", "auto") or "auto").strip().lower()
    except Exception:
        v = "auto"
    if v in ("", "off", "none", "0", "cpu"):
        return None
    if v in ("nnapi", "NnapiExecutionProvider"):
        return "NnapiExecutionProvider"
    if v in ("webgpu", "WebGpuExecutionProvider"):
        return "WebGpuExecutionProvider"
    if v in ("xnnpack", "XnnpackExecutionProvider"):
        return "XnnpackExecutionProvider"
    if v in ("cuda", "CUDAExecutionProvider"):
        return "CUDAExecutionProvider"
    if v in ("dml", "directml", "DmlExecutionProvider"):
        return "DmlExecutionProvider"
    try:
        avail = list(ort.get_available_providers())
    except Exception:
        avail = []
    for cand in ("CUDAExecutionProvider", "DmlExecutionProvider",
                 "XnnpackExecutionProvider", "NnapiExecutionProvider",
                 "WebGpuExecutionProvider"):
        if cand in avail:
            return cand
    return None


def _lama_ep_cache_path(model_path: str) -> str:
    return str(model_path) + ".epab"


def _lama_ep_cached(model_path: str):
    try:
        if os.environ.get("MANGA_ORT_EP_REPROBE", "0") == "1":
            return None
        p = _lama_ep_cache_path(model_path)
        if os.path.isfile(p):
            with open(p, "r", encoding="utf-8") as f:
                v = (f.read() or "").strip().lower()
            if v in ("cpu", "xnnpack", "nnapi", "webgpu", "cuda", "dml"):
                return v
    except Exception:
        pass
    return None


def _lama_ep_store(model_path: str, v: str):
    try:
        v = (v or "").strip().lower()
        if v in ("cpuexecutionprovider", ""):
            v = "cpu"
        if v == "directml":
            v = "dml"
        with open(_lama_ep_cache_path(model_path), "w", encoding="utf-8") as f:
            f.write(v)
    except Exception:
        pass


def _ep_ab_feed(sess, side: int = 256) -> dict:
    feed = {}
    for inp in sess.get_inputs():
        try:
            dt = getattr(inp, "type", "") or ""
        except Exception:
            dt = ""
        if "int64" in dt:
            np_dt = np.int64
        elif "int32" in dt:
            np_dt = np.int32
        elif "float16" in dt:
            np_dt = np.float16
        elif "double" in dt:
            np_dt = np.float64
        elif "bool" in dt:
            np_dt = np.bool_
        else:
            np_dt = np.float32
        shp = []
        try:
            for d in (inp.shape or []):
                shp.append(d if isinstance(d, int) and d > 0 else None)
        except Exception:
            shp = []
        nm = (getattr(inp, "name", "") or "").lower()
        is_mask = ("mask" in nm or "msk" in nm)
        if np_dt in (np.int64, np.int32) and len(shp) <= 2:
            dims = [d if d is not None else (2 if len(shp) >= 2 else 1)
                    for d in (shp or [1, 2])]
            arr = np.full(dims, side, dtype=np_dt)
            feed[inp.name] = arr
            continue
        if len(shp) == 4:
            b = shp[0] or 1
            c = shp[1] if shp[1] else (1 if is_mask else 3)
            h = shp[2] or side
            w = shp[3] or side
            arr = np.zeros((b, c, h, w), dtype=np_dt)
            if np_dt == np.float32 and is_mask:
                h2, w2 = arr.shape[2], arr.shape[3]
                arr[:, :, h2 // 4:h2 // 2, w2 // 4:w2 // 2] = 1.0
            feed[inp.name] = arr
            continue
        if len(shp) == 3:
            dims = [shp[0] or 1, shp[1] or side, shp[2] or side]
            feed[inp.name] = np.zeros(dims, dtype=np_dt)
            continue
        if len(shp) in (0, 1):
            feed[inp.name] = np.zeros([d or 1 for d in shp] or [1], dtype=np_dt)
            continue
        dims = [d if d is not None else 1 for d in shp] or [1]
        feed[inp.name] = np.zeros(dims, dtype=np_dt)
    return feed


_LAMA_STATIC_SIDE = None


def _lama_static_side() -> int:
    """v1.14.66 — شکلِ ثابتِ پچِ LaMa برایِ EPهایی که با شکلِ داینامیک
    می‌میرند (xnnpack رویِ اندروید: پروبِ ثابت پاس می‌شود ولی پچِ واقعیِ
    384×~200 ORT_FAIL می‌دهد — ریشهٔ مرگِ LaMa و فال‌بکِ OpenCV). وقتی
    فعال باشد، هر ورودیِ LaMa دقیقاً به (side×side) پد می‌شود → xnnpack
    فقط یک‌بار کامپایل می‌کند و واقعاً کار می‌کند (سریع‌تر از CPUِ خالی).
    env: MANGA_LAMA_STATIC_SIDE=0 (خاموش) | N (اندازه) | خالی = خودکار
    (اندروید + xnnpack موجود → 384، بقیه → 0)."""
    global _LAMA_STATIC_SIDE
    if _LAMA_STATIC_SIDE is not None:
        return int(_LAMA_STATIC_SIDE)
    v = -1
    try:
        _raw = (os.environ.get("MANGA_LAMA_STATIC_SIDE", "") or "").strip()
        if _raw != "":
            v = int(_raw)
    except Exception:
        v = -1
    side = 0
    if v > 0:
        side = (int(v) // 64) * 64
    elif v == 0:
        side = 0
    else:
        try:
            if _on_android() and ort is not None and (
                    "XnnpackExecutionProvider"
                    in list(ort.get_available_providers())):
                side = 384
        except Exception:
            side = 0
    _LAMA_STATIC_SIDE = int(side)
    return int(side)


def _lama_probe_side(ab: bool = False) -> int:
    """شکلِ فیدِ پروب/AB — وقتی باکتِ ثابت فعال است، پروب باید با همان
    شکلِ واقعیِ پچ‌ها باشد تا کامپایلِ xnnpack از همان ابتدا درست باشد."""
    s = _lama_static_side()
    if s > 0:
        return s
    return 256 if ab else 64


def _ep_ab_time(sess) -> float:
    try:
        feed = _ep_ab_feed(sess, side=_lama_probe_side(True))
        if not feed:
            return float("inf")
        outs = [o.name for o in sess.get_outputs()][:1]
        best = float("inf")
        for i in range(3):
            t0 = time.time()
            sess.run(outs, feed)
            dt = time.time() - t0
            if i > 0 and dt < best:
                best = dt
        return best
    except Exception:
        return float("inf")


def _lama_probeok_path(model_path: str) -> str:
    return str(model_path) + ".probeok"


def _lama_probeok_key(model_path: str, ep_name: str) -> str:
    _v = "x"
    try:
        _v = str(getattr(ort, "__version__", "x") or "x")
    except Exception:
        pass
    try:
        _side = int(_lama_static_side())
    except Exception:
        _side = 0
    try:
        _sz = int(os.path.getsize(model_path)) if model_path else 0
    except Exception:
        _sz = 0
    _ep = str(ep_name or "").lower().replace("executionprovider", "")
    return f"{_ep}|{_v}|{_side}|{_sz}"


def _lama_probeok_hit(model_path, ep_name) -> bool:
    try:
        if not model_path or not isinstance(model_path, str):
            return False
        if os.environ.get("MANGA_ORT_EP_REPROBE", "0") == "1":
            return False
        p = _lama_probeok_path(model_path)
        if not os.path.isfile(p):
            return False
        with open(p, "r", encoding="utf-8") as f:
            v = (f.read() or "").strip()
        return v == _lama_probeok_key(model_path, ep_name) + "|ok"
    except Exception:
        return False


def _lama_probeok_store(model_path, ep_name) -> None:
    try:
        if not model_path or not isinstance(model_path, str):
            return
        with open(_lama_probeok_path(model_path), "w", encoding="utf-8") as f:
            f.write(_lama_probeok_key(model_path, ep_name) + "|ok")
    except Exception:
        pass


def _ort_probe_ok(sess, threads: int, model_path=None,
                  ep_name: str = "") -> bool:
    _t70 = time.time()
    # v1.14.70 — کشِ نتیجهٔ پروب: پروبِ سلامت/سریالی تا ۵ اینفرنسِ
    # ۳۸۴² رویِ xnnpack انجام می‌دهد (رویِ گوشی ده‌ها ثانیه) و در هر
    # استارت تکرار می‌شد؛ نتیجه برایِ (مدل، EP، نسخهٔ ORT، ساید، حجم)
    # ماندگار می‌شود. MANGA_ORT_EP_REPROBE=1 → پروبِ دوباره.
    try:
        if _lama_probeok_hit(model_path, ep_name):
            try:
                print("    [*] پروبِ EP از کش — بدونِ اینفرنسِ دوباره",
                      flush=True)
            except Exception:
                pass
            return True
    except Exception:
        pass
    try:
        feed = _ep_ab_feed(sess, side=_lama_probe_side(False))
        if not feed:
            try:
                print("    [!] پروب: فیدِ خالی (شکلِ ورودیِ مدل؟)")
            except Exception:
                pass
            return False
        outs = [o.name for o in sess.get_outputs()][:1]
        try:
            sess.run(outs, feed)
        except Exception as _pe:
            try:
                print(f"    [!] پروبِ run با نام خروجی: {str(_pe)[:110]}")
            except Exception:
                pass
            try:
                sess.run(None, feed)
            except Exception as _pe2:
                try:
                    print(f"    [!] پروبِ run هم با None: {str(_pe2)[:110]}")
                except Exception:
                    pass
                return False
        if threads <= 0:
            _lama_probeok_store(model_path, ep_name)
            return True
        t0 = time.time()
        try:
            sess.run(outs, feed)
            sess.run(outs, feed)
            t_ser = time.time() - t0
        except Exception:
            return False
        if t_ser <= 0.02:
            _lama_probeok_store(model_path, ep_name)
            return True
        # v1.14.70 — اندروید: فقط اعتبارسنجی (۱ ران کافی است)؛
        # مقایسهٔ سریال/موازی ۴ اینفرنسِ اضافه می‌خواهد و رویِ گوشیِ
        # کم‌رم ده‌ها ثانیه به استارت اضافه می‌کند، درحالی‌که A/Bِ
        # واقعی (.epab) جداگانه EP را با CPU مقایسه کرده است.
        try:
            _and70 = _on_android()
        except Exception:
            _and70 = False
        if _and70:
            try:
                print(f"[TIME] lama-probe={time.time() - _t70:.1f}s "
                      f"(اندروید: فقط اعتبارسنجی)", flush=True)
            except Exception:
                pass
            _lama_probeok_store(model_path, ep_name)
            return True
        # v1.14.67 — امولاتورِ x86_64: رانِ موازیِ همزمان در libonnxruntimeِ
        # x86_64 SIGFPE می‌دهد (تقسیمِ صحیحِ صفر در زمان‌بندِ thread-pool) —
        # پروبِ موازی رویِ x86 بی‌معناست (CI فقط درستی می‌سنجد) → پرش.
        try:
            import platform as _pf67
            if _pf67.machine().lower() in ("x86_64", "amd64"):
                return True
        except Exception:
            pass
        from concurrent.futures import ThreadPoolExecutor as _TPE
        try:
            with _TPE(max_workers=2) as ex:
                t1 = time.time()
                f1 = ex.submit(sess.run, outs, feed)
                f2 = ex.submit(sess.run, outs, feed)
                f1.result(timeout=60)
                f2.result(timeout=60)
                t_con = time.time() - t1
        except Exception:
            return False
        if t_con > t_ser * 1.6:
            try:
                print(f"    [!] EP رانِ همزمان را سریال می‌کند "
                      f"({t_con:.2f}s در برابر ۲×{t_ser:.2f}s) → CPU موازی")
            except Exception:
                pass
            return False
        try:
            print(f"[TIME] lama-probe={time.time() - _t70:.1f}s", flush=True)
        except Exception:
            pass
        _lama_probeok_store(model_path, ep_name)
        return True
    except Exception:
        return False


_AB_EPS = ["XnnpackExecutionProvider", "NnapiExecutionProvider",
           "WebGpuExecutionProvider", "CUDAExecutionProvider",
           "DmlExecutionProvider"]


def _ep_tournament(model_path: str, threads: int, include_gpu: bool = True):
    t_all0 = time.time()
    try:
        budget = float(os.environ.get("MANGA_AB_BUDGET", "45") or 45)
    except Exception:
        budget = 45.0
    try:
        avail = list(ort.get_available_providers())
    except Exception:
        avail = []
    rows = []
    for cand in _AB_EPS:
        short = cand.replace("ExecutionProvider", "").lower()
        if cand not in avail:
            continue
        if cand in ("CUDAExecutionProvider", "DmlExecutionProvider") \
                and not include_gpu:
            continue
        if (time.time() - t_all0) > budget:
            try:
                print(f"    [*] {short}: رد شد (اتمام بودجهٔ {budget:.0f}s پروب)")
            except Exception:
                pass
            continue
        s_c = None
        try:
            # v1.14.99-speed (SRV-L) — کاندیدِ CUDA تورنمنت هم گاردِ سقفِ
            # نخِ GPU را می‌گیرد (SIGABRTِ SRV-K g20 در per-patchِ LaMa)
            so_c = _ort_session_options(
                threads,
                prefer_gpu=(cand == "CUDAExecutionProvider"))
            try:
                so_c.append_execution_provider(cand)
            except Exception:
                try:
                    so_c._eps = [(cand, {})]
                except Exception:
                    pass
            t0 = time.time()
            # v1.14.98-speed (SRV-H3) — کاندیدِ CUDA در تورنمنت هم همان
            # optionsِ سشنِ نهایی را بگیرد (workspace + MANGA_CUDNN_ALGO)
            # تا A/B با کانفیگِ نهایی قابلِ مقایسه باشد؛ برایِ بقیهٔ EPها
            # None = دقیقاً رفتارِ قبل.
            _po_h3 = (_build_provider_options(
                [cand, "CPUExecutionProvider"])
                if cand == "CUDAExecutionProvider" else None)
            s_c = ort.InferenceSession(model_path, sess_options=so_c,
                                       providers=[cand, "CPUExecutionProvider"],
                                       provider_options=_po_h3)
            t_make = time.time() - t0
            if not _ort_probe_ok(s_c, threads if threads > 0 else 0,
                                 model_path, cand):
                try:
                    print(f"    [*] {short}: مردود (پروب سلامت/سریالی)")
                except Exception:
                    pass
                s_c = None
                continue
            t_c = _ep_ab_time(s_c)
            try:
                print(f"    [*] پروب {short}: {t_c:.2f}s (ساخت {t_make:.1f}s)")
            except Exception:
                pass
            rows.append((t_c, short, s_c))
        except Exception as e:
            try:
                print(f"    [*] {short}: ناموفق ({str(e)[:90]})")
            except Exception:
                pass
            s_c = None
            continue
    s_cpu, t_cpu = None, float("inf")
    if _on_x86():
        # v1.14.67 — سشنِ CPU رویِ x86 ساخته می‌شود ولی run نمی‌شود
        # (SIGFPE)؛ فقط برایِ فال‌بکِ نهایی
        try:
            s_cpu = ort.InferenceSession(model_path,
                                         sess_options=_ort_session_options(
                                             threads),
                                         providers=["CPUExecutionProvider"])
        except Exception:
            s_cpu = None
    else:
        try:
            s_cpu = ort.InferenceSession(
                model_path,
                sess_options=_ort_session_options(threads),
                providers=["CPUExecutionProvider"])
            t_cpu = _ep_ab_time(s_cpu)
            try:
                print(f"    [*] پروب CPU: {t_cpu:.2f}s")
            except Exception:
                pass
        except Exception:
            pass
    rows.sort(key=lambda r: r[0])
    # v1.14.67 — امولاتورِ x86_64: مقایسه با CPU (سشنِ CPU) خودش کرش
    # می‌کند → برندهٔ سخت‌افزاریِ پروب‌شده را بی‌مقایسه بپذیر
    if _on_x86():
        if rows:
            winner = rows[0]
            try:
                print(f"[*] پروب EP (x86 — بدونِ مقایسه با CPU): {winner[1]}")
            except Exception:
                pass
            _lama_ep_store(model_path, winner[1])
            return winner[2]
        _lama_ep_store(model_path, "cpu")
        return s_cpu
    winner = rows[0] if (rows and rows[0][0] < t_cpu) else None
    try:
        summary = " | ".join(f"{r[1]} {r[0]:.2f}s" for r in rows) or "—"
        print(f"[*] پروب EP ({os.path.basename(model_path)}): "
              f"{summary} | CPU {t_cpu:.2f}s → برنده: "
              f"{winner[1] if winner else 'CPU'}")
    except Exception:
        pass
    if winner is not None:
        _lama_ep_store(model_path, winner[1])
        try:
            print(f"[+] شتاب سخت‌افزاری ORT فعال شد: {winner[1]} "
                  f"(پروب A/B — سریع‌تر از CPU)")
        except Exception:
            pass
        return winner[2]
    _lama_ep_store(model_path, "cpu")
    return s_cpu


def _make_ort_session(model_path: str, prefer_gpu: bool = True, threads: int = 4,
                      ep: Optional[str] = None, ep_ab: bool = False):
    global _ORT_CUDA_OK
    if ort is None:
        raise RuntimeError("onnxruntime نصب نیست")
    # v1.14.67 — امولاتورِ x86_64 (CI): CPU-EPِ ORT-android در createSession
    # SIGFPE می‌دهد و تورنمنت هم پروب را رد می‌کند → سشنِ دومِ fallback
    # کرشِ نیتیو می‌دهد. تجربهٔ ران ۲۴: ساختِ اولینِ سشنِ XNNPACK سالم بود؛
    # پس: هیچ تورنمنت، هیچ پروب، هیچ سشنِ دوم — فقط یک سشنِ مستقیمِ
    # XNNPACK+CPU (گره‌هایِ پشتیبانی‌نشده خودکار به CPU برمی‌گردند).
    try:
        import platform as _pf86
        if _on_android() and _pf86.machine().lower() in ("x86_64", "amd64"):
            so86 = _ort_session_options(1)
            try:
                so86.append_execution_provider("XnnpackExecutionProvider")
            except Exception:
                try:
                    so86._eps = [("XnnpackExecutionProvider", {})]
                except Exception:
                    pass
            sess86 = ort.InferenceSession(
                model_path, sess_options=so86,
                providers=["XnnpackExecutionProvider", "CPUExecutionProvider"])
            try:
                print("[*] x86_64: سشنِ مستقیمِ XNNPACK (بدونِ تورنمنت/پروب)")
            except Exception:
                pass
            return sess86
    except Exception as e:
        try:
            print(f"[!] x86_64 سشنِ مستقیمِ XNNPACK ناموفق: {str(e)[:110]}")
        except Exception:
            pass
    # v1.14.99-speed (SRV-L) — «want» قبل از ساختِ سشن محاسبه می‌شود تا
    # گاردِ سقفِ نخِ GPU (SIGABRT ≥۲۰ رویِ CUDA/TRT) رویِ سشنِ اصلی هم
    # اعمال شود؛ مسیرِ CPU بدونِ clamp می‌ماند.
    want = prefer_gpu and (_ORT_CUDA_OK is not False)
    so = _ort_session_options(threads, prefer_gpu=want)

    if want:
        _prepare_ort_cuda_dlls()

    _EP_SHORT2FULL = {"xnnpack": "XnnpackExecutionProvider",
                      "nnapi": "NnapiExecutionProvider",
                      "webgpu": "WebGpuExecutionProvider",
                      "cuda": "CUDAExecutionProvider",
                      "dml": "DmlExecutionProvider"}
    if ep and ep_ab:
        _cached = _lama_ep_cached(model_path)
        if _cached == "cpu":
            ep, ep_ab = None, False
        elif _cached in _EP_SHORT2FULL:
            ep, ep_ab = _EP_SHORT2FULL[_cached], False
    elif ep and not ep_ab:
        pass  # EPِ اجباری (MANGA_ORT_EP) — کشِ opt خودش بر اساسِ EP کلید می‌خورد

    if ep:
        try:
            avail = list(ort.get_available_providers())
        except Exception:
            avail = []
        _any_hw = ep in avail or any(c in avail for c in _AB_EPS)
        if _any_hw and ep_ab:
            s_win = _ep_tournament(model_path, threads, include_gpu=prefer_gpu)
            if s_win is not None:
                return s_win
            import gc as _gcp
            try:
                _gcp.collect()
            except Exception:
                pass
        elif ep in avail:
            # v1.14.99-speed (SRV-L) — مسیرِ EPِ اجباری: اگر CUDA اجباری
            # است، گاردِ سقفِ نخِ GPU اعمال شود
            so_ep = _ort_session_options(
                threads, prefer_gpu=(ep == "CUDAExecutionProvider"))
            try:
                so_ep.append_execution_provider(ep)
            except Exception:
                try:
                    so_ep._eps = [(ep, {})]
                except Exception:
                    pass
            try:
                # v1.14.98-speed (SRV-H3) — مسیرِ EPِ اجباری هم optionsِ
                # CUDAِ مرکزی را می‌گیرد (workspace + MANGA_CUDNN_ALGO) تا
                # «همهٔ» سشن‌هایِ CUDA یک کانفیگ داشته باشند؛ برایِ epهای
                # غیرِ CUDA خروجیِ _build_provider_options None است.
                s_ep = _lama_session_cached(
                    model_path, so_ep, [ep, "CPUExecutionProvider"],
                    provider_options=_build_provider_options(
                        [ep, "CPUExecutionProvider"]))
                if _ort_probe_ok(s_ep, threads if threads > 0 else 0,
                                 model_path, ep):
                    try:
                        print(f"[+] شتاب سخت‌افزاری ORT فعال شد: {ep} "
                              f"(MANGA_ORT_EP — اجباری)")
                    except Exception:
                        pass
                    return s_ep
                try:
                    s_ep = None
                except Exception:
                    pass
            except Exception as e:
                try:
                    print(f"    [!] ساخت سشن {ep} ناموفق ({str(e)[:120]}) → CPU")
                except Exception:
                    pass
            import gc as _gcp
            try:
                _gcp.collect()
            except Exception:
                pass
        else:
            try:
                print(f"    [!] {ep} در این ORT نیست (available={avail}) → CPU")
            except Exception:
                pass

    # v1.14.96-speed — EPها از انتخابگرِ مرکزیِ _best_providers_for
    # می‌آیند (TensorRT/CUDA/ROCm/MIGraphX/Dml/… بر اساسِ آنچه واقعاً
    # نصب است + XNNPACKِ امولاتور + CPU همیشه آخر) — به‌جای چکِ
    # هاردکدِ CUDA که بقیهٔ EPهایِ GPU را از قلم می‌انداخت.
    providers = _best_providers_for("lama", prefer_gpu=want)
    # v1.14.96-speed (SRV-G phase2) — CUDA EP options
    # (cudnn_conv_use_max_workspace=1) + XNNPACKِ A/B (intra=فیزیکی)
    _popts = _build_provider_options(providers)

    try:
        # v1.14.69 — کشِ مدلِ بهینه‌شده (گوشی: createSession تا 67s طول
        # می‌کشد؛ بارهایِ بعدی از فایلِ بهینه‌شده ساخته می‌شوند)
        sess = _lama_session_cached(model_path, so, providers,
                                    provider_options=_popts)
    except Exception as e:
        print(f"[!] InferenceSession GPU ناموفق ({e}) → CPU")
        _ORT_CUDA_OK = False
        sess = ort.InferenceSession(
            model_path, sess_options=so, providers=["CPUExecutionProvider"]
        )

    active = list(sess.get_providers())
    if want and "CUDAExecutionProvider" in active:
        _ORT_CUDA_OK = True
    elif want:
        _ORT_CUDA_OK = False
        print(
            f"[!] session providers={active} (CUDA ساخته نشد؛ "
            f"اغلب کمبود cuDNN/cublas). "
            f"امتحان: pip install 'onnxruntime-gpu[cuda,cudnn]==1.26.0'"
        )
    return sess


def _cpu_thread_fallback(session, model_path: str, use_threads: int,
                         allow_bump: bool = True):


    try:
        # v1.14.67 — x86_64: بازسازیِ سشنِ CPU = SIGFPE → دست‌نخورده برگرد
        import platform as _pf86
        if _on_android() and _pf86.machine().lower() in ("x86_64", "amd64"):
            return session, use_threads
        provs = list(session.get_providers())
        _cap = 4 if _on_android() else 8
        cpu_n = max(1, min(_cap, os.cpu_count() or 4))
        # v1.14.99 (SRV-H4) — شرطِ e32bccf بازگشت (گاردِ use_threads>0یِ
        # SRV-G حذف شد؛ use_threads در تماس‌گیرنده‌ها همیشه ≥1 clamp شده)
        if (allow_bump and "CUDAExecutionProvider" not in provs
                and use_threads < cpu_n):
            print(f"    [*] اینپینت روی CPU است → threads: {use_threads} → {cpu_n}")
            return _make_ort_session(model_path, prefer_gpu=False, threads=cpu_n), cpu_n
    except Exception:
        pass
    return session, use_threads


class LamaONNX:

    REPO = "Carve/LaMa-ONNX"
    FILE = "lama_fp32.onnx"

    def __init__(self, model_path: Optional[str] = None, prefer_gpu: bool = True,
                 size: int = 512, threads: int = 4, cache_dir: Optional[str] = None):
        self.prefer_gpu = bool(prefer_gpu)
        self.size = 256 if not prefer_gpu else size
        if not model_path or not os.path.isfile(model_path):
            model_path = self._download_model(cache_dir=cache_dir)
        self.model_path = model_path


        if not prefer_gpu:
            try:
                use_threads = int(os.environ.get("MANGA_LAMA_THREADS", "0") or 0)
            except Exception:
                use_threads = 0
            if use_threads <= 0:
                use_threads = 2
            use_threads = max(1, min(use_threads, os.cpu_count() or 4))
        else:
            use_threads = max(1, int(threads))
        self.session = _make_ort_session(model_path, prefer_gpu=prefer_gpu,
                                         threads=use_threads,
                                         ep=_resolve_lama_ep(),
                                         ep_ab=_is_auto_ep())
        self.session, use_threads = _cpu_thread_fallback(
            self.session, model_path, use_threads, allow_bump=False)
        print(
            f"[+] LaMa ONNX آماده | providers={self.session.get_providers()} | "
            f"threads={use_threads} | max_size={self.size}"
        )
        names = [i.name for i in self.session.get_inputs()]
        self._in_image = names[0]
        self._in_mask = names[1] if len(names) > 1 else "mask"
        for n in names:
            low = n.lower()
            if "mask" in low:
                self._in_mask = n
            elif "image" in low or "img" in low:
                self._in_image = n


        self._fixed_size = False
        try:
            for inp in self.session.get_inputs():
                dims = list(inp.shape)[-2:]
                fixed = [d for d in dims if isinstance(d, int) and d > 0]
                if len(fixed) == 2 and fixed[0] == fixed[1] and fixed[0] >= 64:
                    self.size = fixed[0]
                    self._fixed_size = True
                    break
        except Exception:
            pass

    @classmethod
    def _download_model(cls, cache_dir: Optional[str] = None) -> str:
        from pathlib import Path
        cache_root = Path(cache_dir) if cache_dir else Path.home() / ".cache" / "manga_translator_models"
        cache_root.mkdir(parents=True, exist_ok=True)

        _m = _mirror_model(cls.FILE)
        if _m:
            return _m
        print(f"[*] دانلود مدل LaMa ONNX از {cls.REPO} ...")
        if hf_hub_download is None:
            raise RuntimeError("huggingface_hub لازم است")
        cand = hf_hub_download(repo_id=cls.REPO, filename=cls.FILE, cache_dir=cache_dir)
        try:
            import shutil as _sh
            _dst = os.path.join(_model_cache_dir("det_models"), cls.FILE)
            if not os.path.isfile(_dst):
                _sh.copyfile(cand, _dst)
        except Exception:
            pass
        return cand

    def _pick_size(self, w: int, h: int) -> int:
        m = max(int(w), int(h))
        if getattr(self, "_fixed_size", False):
            return self.size
        if not self.prefer_gpu:
            return 256
        if m <= 180:
            return 256
        if m <= 320:
            return 384
        return min(self.size, 512)

    def __call__(self, image, mask):
        if isinstance(image, np.ndarray):
            if image.ndim == 3 and image.shape[2] in (3, 4):
                img_rgb = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)
            else:
                img_rgb = cv2.cvtColor(image, cv2.COLOR_GRAY2RGB)
        else:
            img_rgb = np.array(image.convert("RGB"))
        if isinstance(mask, np.ndarray):
            if mask.ndim == 3:
                mask_u8 = mask[..., 0] if mask.shape[2] == 1 else cv2.cvtColor(mask, cv2.COLOR_BGR2GRAY)
            else:
                mask_u8 = mask
        else:
            mask_u8 = np.array(mask.convert("L"))
        if mask_u8.shape != img_rgb.shape[:2]:
            raise ValueError("Image and mask dimensions must match")
        original_mask = mask_u8 > 0
        if not np.any(original_mask):
            return Image.fromarray(img_rgb.copy())
        orig_size = (img_rgb.shape[1], img_rgb.shape[0])
        run_size = self._pick_size(orig_size[0], orig_size[1])
        if not self.prefer_gpu and not getattr(self, "_fixed_size", False):
            cov = float(np.count_nonzero(original_mask)) / float(original_mask.size)
            if cov > 0.22:
                run_size = 512

        scale = run_size / max(orig_size)
        rw, rh = (max(1, round(d * scale)) for d in orig_size)
        interp = cv2.INTER_AREA if max(img_rgb.shape[:2]) > run_size else cv2.INTER_CUBIC
        img_np = cv2.resize(img_rgb, (rw, rh), interpolation=interp)
        mask_interp = cv2.INTER_AREA if scale < 1 else cv2.INTER_NEAREST_EXACT
        msk = (cv2.resize(original_mask.astype(np.float32), (rw, rh),
                          interpolation=mask_interp) > 0).astype(np.uint8)
        img_np = cv2.copyMakeBorder(img_np, 0, run_size - rh, 0, run_size - rw, cv2.BORDER_REFLECT)

        msk = cv2.copyMakeBorder(msk, 0, run_size - rh, 0, run_size - rw, cv2.BORDER_REFLECT)
        img_np[msk > 0] = 0

        img_in = img_np.astype(np.float32) / 255.0
        mask_in = msk.astype(np.float32)
        img_in = img_in.transpose(2, 0, 1)[None]
        mask_in = mask_in[None, None]
        out = self.session.run(None, {self._in_image: img_in, self._in_mask: mask_in})[0]

        o = out[0].transpose(1, 2, 0).astype(np.float32)
        try:
            if float(np.max(o)) <= 1.5:
                o = o * 255.0
        except Exception:
            pass
        out = np.clip(o, 0, 255).astype(np.uint8)

        predicted = cv2.resize(out[:rh, :rw], orig_size, interpolation=cv2.INTER_LANCZOS4)
        result = img_rgb.copy()
        result[original_mask] = predicted[original_mask]
        return Image.fromarray(result)


class LamaMangaONNX:


    URL = ("https://github.com/amirwolf512k/Manga-AutoTranslate/"
           "releases/download/models/lama-manga-dyn.onnx")
    # v1.14.115 — واریانتِ «بدونِ DFT» (همان وزنهای big-lama؛ بلوکهایِ
    # Fourier به ماتمولِ کسینوسی/سینوسی صادر شدهاند — فایلِ عمومیِ
    # K3-Manga-AutoTranslate-Mobile v4.1.1، وزنها Apache-2.0).
    # وریفایِ عددی (scripts/lama_equiv.py): خروجی در برابرِ lama-manga-dyn
    # رویِ ورودیِ تصادفی 384×384 → cosine=1.0000 MAE=0.002؛ سرعتِ CPU:
    # 2.0s در برابرِ 8.2s (~۴×). DFT (144 نود) رویِ CPU/ARM گوشی سم است.
    NOFFT_URL = ("https://github.com/amirwolf512k/Manga-AutoTranslate/"
                 "releases/download/models/lama-manga-nofft.onnx")
    FALLBACK_URL = "https://huggingface.co/mayocream/lama-manga-onnx/resolve/main/lama-manga.onnx"
    SIZE = 512

    @staticmethod
    def _want_nofft() -> bool:
        """v1.14.147: پیشفرضِ همهجا «بدونِ DFT» — همان وزنهایِ big-lama با
        بلوکهایِ Fourier به ماتمولِ کسینوسی/سینوسی؛ وریفایِ عددیِ
        scripts/lama_equiv.py: cosine=1.0000 MAE=0.002 در برابرِ dyn →
        خروجی و سبکِ پاکسازی دستنخورده، CPU چند برابر سریعتر (8.2s→2.0s).
        MANGA_LAMA_NOFFT=0 برایِ برگشتِ دستی به dyn (مثلاً GPU که DFT را
        ارزان میدهد)."""
        _env = str(os.environ.get("MANGA_LAMA_NOFFT", "") or "").strip()
        if _env == "1":
            return True
        if _env == "0":
            return False
        return True

    def __init__(self, model_path: Optional[str] = None, prefer_gpu: bool = True,
                 threads: int = 4, cache_dir: Optional[str] = None):
        self.prefer_gpu = bool(prefer_gpu)
        if not model_path or not os.path.isfile(model_path):
            model_path = self._download_model(cache_dir=cache_dir)
        self.model_path = model_path
        if not prefer_gpu:
            try:
                use_threads = int(os.environ.get("MANGA_LAMA_THREADS", "0") or 0)
            except Exception:
                use_threads = 0
            if use_threads <= 0:
                # v1.14.45: نخِ صریحِ فراهم‌شده از _get_lama(threads=…) محترم است —
                # وقتی پچِ موازی کم است باید هر پچ چندنخی شود (هسته‌های بیکار نماند)
                if threads and int(threads) > 0:
                    use_threads = max(1, min(int(threads), os.cpu_count() or 4))
                else:
                    # v1.14.147: PC تا ۴ نخ (با nofft چند برابر سریعتر میشود؛
                    # اندروید مثلِ قبل ۱ — گاردِ رم/بزرگ.لیتلِ خودش را دارد)
                    _cap = 1 if _on_android() else 4
                    use_threads = max(1, min(_cap, os.cpu_count() or 4))
        else:
            use_threads = max(1, int(threads or 1))
        self.thr_used = int(use_threads)
        self.ep_used = None
        try:
            self.ep_used = _resolve_lama_ep()
        except Exception:
            self.ep_used = None
        self.session = _make_ort_session(model_path, prefer_gpu=prefer_gpu,
                                         threads=use_threads, ep=self.ep_used,
                                         ep_ab=_is_auto_ep())
        self.session, use_threads = _cpu_thread_fallback(
            self.session, model_path, use_threads, allow_bump=False)
        # v1.14.52 — صداقتِ ep_used: رویِ اندروید _resolve_lama_ep مثلاً
        # Xnnpack/Nnapi برمی‌گرداند ولی _make_ort_session با کشِ «cpu» به
        # CPUExecutionProvider سقوط می‌کند و ep_used همان EPِ درخواستی
        # می‌ماند → شرطِ سوئیچِ نخِ _get_lama («فقط رویِ CPU») برای همیشه
        # رد می‌شد و زمان‌بند روی «۲ پچ × ۴ نخ»یِ کند می‌ماند (لاگِ POCO F4:
        # strip ۸۲.۳s!). حالا EPِ واقعیِ سشن ملاک است.
        try:
            _aps = [str(p) for p in self.session.get_providers()]
            if _aps and all(p.lower().startswith("cpu") for p in _aps):
                self.ep_used = None
        except Exception:
            pass
        self.thr_used = int(use_threads)  # fallback ممکن است نخ را عوض کند
        names = [i.name for i in self.session.get_inputs()]
        self._in_image = names[0]
        self._in_mask = names[1] if len(names) > 1 else "mask"
        # v1.14.66 — باکتِ شکلِ ثابت برایِ xnnpack: هر ورودیِ LaMa دقیقاً
        # _static_bucket×_static_bucket پد می‌شود تا EPِ xnnpack که با
        # شکلِ داینامیک ORT_FAIL می‌دهد واقعاً کار کند (پچِ LaMa زنده
        # می‌ماند → بدونِ فال‌بکِ OpenCV → بدونِ لکهٔ قرمز + سریع‌تر).
        self._static_bucket = 0
        # v1.14.135 — پچِ تطبیقیِ LaMa (فقط اندروید — MANGA_LAMA_PATCH512):
        # پچِ 384 کلِ ورودی را به مقیاسِ ~0.5 (بلوکِ تمامعرض) و ~0.2
        # (گروهِ پراکنده) له میکند → LaMa «متنِ قلابی» میسازد (لکهٔ
        # کثیف). با رمِ آزادِ ≥1200MB و ≥۶ هسته، پچِ 512 (کیفیتِ
        # بالاتر) امن است؛ گوشیِ کم‌رم مثلِ قبل 384 میماند. env دستی
        # (MANGA_LAMA_PATCH_SIDE) همیشه حاکم است.
        try:
            if (_on_android()
                    and not os.environ.get("MANGA_LAMA_PATCH_SIDE")
                    and _android_gate("MANGA_LAMA_PATCH512")):
                _free_mb135 = 0
                with open("/proc/meminfo", "r") as _mi135:
                    for _ln135 in _mi135:
                        if _ln135.startswith("MemAvailable:"):
                            _free_mb135 = int(_ln135.split()[1]) // 1024
                            break
                if _free_mb135 >= 1200 and (os.cpu_count() or 2) >= 6:
                    os.environ["MANGA_LAMA_PATCH_SIDE"] = "512"
                    os.environ["MANGA_LAMA_STATIC_SIDE"] = "512"
                    globals()["_LAMA_STATIC_SIDE"] = None  # بازخوانیِ کش
                    print("[*] پچِ تطبیقی LaMa: رمِ آزادِ کافی → 512",
                          flush=True)
        except Exception:
            pass
        try:
            _pv66 = [str(p).lower()
                     for p in (self.session.get_providers() or [])]
            if _lama_static_side() > 0 and any(
                    p.startswith("xnnpack") for p in _pv66):
                self._static_bucket = int(_lama_static_side())
                print(f"[*] LaMa xnnpack → پچِ ثابتِ "
                      f"{self._static_bucket}×{self._static_bucket} "
                      f"(ضدِ ORT_FAILِ شکلِ داینامیک)", flush=True)
        except Exception:
            self._static_bucket = 0
        self._input_cap = self.SIZE
        try:
            _env_ps = int(os.environ.get("MANGA_LAMA_PATCH_SIDE", "0") or 0)
        except Exception:
            _env_ps = 0
        if _env_ps > 0:
            self._input_cap = _env_ps
        elif not prefer_gpu and _on_android():
            self._input_cap = 384
        self._fixed_size = False
        self._dyn_size = 512
        try:
            for inp in self.session.get_inputs():
                dims = list(inp.shape)[-2:]
                fixed = [d for d in dims if isinstance(d, int) and d > 0]
                if len(fixed) == 2 and fixed[0] == fixed[1] and fixed[0] >= 64:
                    self._fixed_size = True
                    self._dyn_size = int(fixed[0])
                    break
        except Exception:
            pass
        print(
            f"[+] مدل پاکسازی آماده | threads={use_threads} | size={self.SIZE}" +
            (f" | سقفِ پچ: {self._input_cap}" if self._input_cap != self.SIZE else "")
        )
        # v1.14.67 — A/B با شکلِ واقعیِ پچ (یک‌بار + کشِ .epab): پروبِ قدیمی
        # با شکلِ کوچک بود؛ xnnpack ممکن است «کار کند» ولی از CPUِ چندنخی
        # کندتر باشد (لاگِ POCO F4: 28.4s برایِ ۲ پچِ ۳۸۴²). برنده ماندگار
        # می‌شود. گیتِ رم: با رمِ آزادِ کم (دو سشن همزمان) A/B نمی‌کنیم.
        try:
            self._ep_real_shape_ab(use_threads)
        except Exception:
            pass
        # ══ v1.14.106 — dual-device (GPU + CPU همزمان) ══════════════════
        # درخواستِ کاربر: «هم GPU هم CPU با هم استفاده کنه واسه پاکسازی
        # سریع‌تر». وقتی EPِ سرِ سشن GPU-گونه است (CUDA/DML/NNAPI/XNNPACK)،
        # یک سشنِ CPUِ دوم ساخته می‌شود و پچ‌هایِ موازیِ همزمان بینِ دو
        # دستگاه می‌چرخند. رویِ ساختهٔ CPU-خالص هیچ تغییری نمی‌کند (سشنِ
        # دوم ساخته نمی‌شود → رگرسیونِ بیت‌به‌بیت محفوظ). گیتِ رم رویِ
        # اندروید: MemAvailable < 2.5GB → نه (دو سشن جا نمی‌شود).
        self.session_cpu = None
        self._sess_rr = 0
        self._sess_rr_lock = threading.Lock()
        try:
            _ghead = _gpu_head_of(self.session)
            if _ghead and _dual_device_enabled() \
                    and (os.cpu_count() or 2) >= 4 \
                    and not _android_x86_emulator():
                # v1.14.108 — رویِ شبیه‌سازِ x86_64 سشنِ CPU-خالص ممنوع است
                # (CPU EPِ ORT-android آنجا می‌میرد — درسِ v1.14.67؛ هنگِ
                # گیتِ شبیه‌ساز)؛ رویِ گوشیِ arm64 و PC مشکلی ندارد.
                _free_mb = 0
                try:
                    with open("/proc/meminfo", "r") as _mi:
                        for _ln in _mi:
                            if _ln.startswith("MemAvailable:"):
                                _free_mb = int(_ln.split()[1]) // 1024
                                break
                except Exception:
                    _free_mb = 0
                if (not (_on_android() or _android_like_env())) or \
                        (not _free_mb or _free_mb >= 2500):
                    self.session_cpu = _lama_session_cached(
                        self.model_path,
                        _ort_session_options(max(1, int(use_threads))),
                        ["CPUExecutionProvider"])
                    print(f"[⚡] پاکسازی dual-device: {_ghead} + CPU "
                          f"همزمان (پچ‌ها می‌چرخند)", flush=True)
        except Exception as _e:
            self.session_cpu = None
            print(f"[!] dual-device پاکسازی غیرفعال ({_e})", flush=True)

    def _ep_real_shape_ab(self, threads: int) -> None:
        try:
            if os.environ.get("MANGA_LAMA_AB", "1") == "0":
                return
            _pv = [str(p).lower()
                   for p in (self.session.get_providers() or [])]
            if not any(p.startswith("xnnpack") for p in _pv):
                return
            if not _on_android():
                return
            if _lama_ep_cached(self.model_path) == "cpu":
                return
            if _on_x86():
                return  # A/B با سشنِ CPU رویِ x86 ممکن نیست (SIGFPEِ ORT)
            # گیتِ رم: MemAvailable < 1.5GB → A/B نه (دو سشن جا نمی‌شود)
            _free_mb = 0
            try:
                with open("/proc/meminfo", "r") as _mi:
                    for _ln in _mi:
                        if _ln.startswith("MemAvailable:"):
                            _free_mb = int(_ln.split()[1]) // 1024
                            break
            except Exception:
                _free_mb = 0
            if _free_mb and _free_mb < 1500:
                try:
                    print(f"    [*] A/Bِ EP رد شد (رمِ آزاد {_free_mb}MB "
                          f"< 1500MB) — همان EP فعلی", flush=True)
                except Exception:
                    pass
                return
            _side = int(self._static_bucket or _lama_probe_side(True) or 384)
            t_hw = _ep_ab_time(self.session)
            if not (t_hw < float("inf")):
                return
            s_cpu = _lama_session_cached(
                self.model_path,
                _ort_session_options(threads),
                ["CPUExecutionProvider"])
            t_cpu = _ep_ab_time(s_cpu)
            try:
                print(f"    [*] A/Bِ واقعیِ {_side}²: xnnpack {t_hw:.2f}s | "
                      f"CPU {t_cpu:.2f}s", flush=True)
            except Exception:
                pass
            if t_cpu < t_hw * 0.85:
                self.session = s_cpu
                self.ep_used = None
                self._static_bucket = 0
                self.thr_used = max(1, int(threads or 1))
                _lama_ep_store(self.model_path, "cpu")
                try:
                    print(f"[+] LaMa → CPU (سریع‌تر از xnnpack رویِ این "
                          f"دستگاه — ماندگار در .epab)", flush=True)
                except Exception:
                    pass
            else:
                try:
                    del s_cpu
                except Exception:
                    pass
                _lama_ep_store(self.model_path, "xnnpack")
        except Exception:
            pass

    @classmethod
    def _download_model(cls, cache_dir: Optional[str] = None) -> str:
        from pathlib import Path
        cache_root = Path(cache_dir) if cache_dir else Path.home() / ".cache" / "manga_translator_models"
        cache_root.mkdir(parents=True, exist_ok=True)
        # v1.14.147 — واریانتِ بدونِDFT همهجا (خروجیِ عددیِ یکسان با dyn —
        # وریفایِ scripts/lama_equiv.py — و CPU چند برابر سریعتر)؛
        # MANGA_LAMA_NOFFT=0 رویِ PC برایِ dynِ قدیمی.
        _nofft = cls._want_nofft()
        dst = cache_root / ("lama-manga-nofft.onnx" if _nofft else "lama-manga-dyn.onnx")
        if dst.is_file() and dst.stat().st_size > 1_000_000:
            print(f"[*] مدل LaMa-Manga ({'بدونِDFT' if _nofft else 'داینامیک'}) از کش: {dst}")
            return str(dst)
        if _nofft:
            print("[*] دانلود مدل LaMa-Manga بدونِDFT (~۲۰۶MB، فقط بار اول) ...")
            urls = (cls.NOFFT_URL, cls.URL,
                    _RAPIDOCR_MIRROR + "lama_fp32.onnx", cls.FALLBACK_URL)
        else:
            print("[*] دانلود مدل LaMa-Manga ONNX داینامیک (~۲۰۶MB، فقط بار اول) ...")
            urls = (cls.URL,
                    _RAPIDOCR_MIRROR + "lama_fp32.onnx",
                    cls.FALLBACK_URL)
        last = None
        for url in urls:
            try:
                host = url.split("/")[2]
                print(f"    دانلود از {host} ...")
                _dl_to(url, str(dst), name="lama_fp32.onnx")
                print(f"[+] مدل LaMa-Manga ذخیره شد: {dst}")
                return str(dst)
            except Exception as e:
                last = e
                print(f"    [!] دانلود از {url.split('/')[2]} نشد: {e}")
                try:
                    if os.path.isfile(str(dst) + ".part"):
                        os.remove(str(dst) + ".part")
                except Exception:
                    pass
        raise RuntimeError(f"دانلود مدل LaMa ناموفق: {last}")

    def _prep_sample(self, image, mask):
        """v1.14.96-speed (SRV-G phase2) — آماده‌سازیِ ورودیِ LaMa-Manga:
        همان کدِ __call__ تا قبل از session.run (بایت‌به‌بایت همان ریاضی).
        خروجی برایِ runِ تکی و batched مشترک است."""
        if isinstance(image, np.ndarray):
            if image.ndim == 3 and image.shape[2] in (3, 4):
                img_rgb = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)
            else:
                img_rgb = cv2.cvtColor(image, cv2.COLOR_GRAY2RGB)
        else:
            img_rgb = np.array(image.convert("RGB"))
        if isinstance(mask, np.ndarray):
            if mask.ndim == 3:
                mask_u8 = mask[..., 0] if mask.shape[2] == 1 else cv2.cvtColor(mask, cv2.COLOR_BGR2GRAY)
            else:
                mask_u8 = mask
        else:
            mask_u8 = np.array(mask.convert("L"))
        if mask_u8.shape != img_rgb.shape[:2]:
            raise ValueError("Image and mask dimensions must match")
        original_mask = mask_u8 > 0
        _has_mask = bool(np.any(original_mask))
        oh, ow = img_rgb.shape[:2]
        s = self._dyn_size if self._fixed_size else min(self.SIZE, self._input_cap)
        _mx = max(ow, oh)

        _bucket66 = int(getattr(self, "_static_bucket", 0) or 0)
        if _bucket66 and not self._fixed_size:
            # v1.14.66 — همهٔ ورودی‌ها دقیقاً _bucket66×_bucket66 → شکلِ
            # ثابت برایِ xnnpack (یک کامپایل، بدونِ ORT_FAILِ شکلِ تازه).
            # ماسک در ناحیهٔ پد صفر است و خروجی فقط داخلِ ناحیهٔ اصلی
            # برش می‌خورد — ریاضیِ خروجی مثلِ مسیرِ fixed-size است.
            s = _bucket66
            scale = s / _mx
            if scale < 1.0:
                rw, rh = max(1, round(ow * scale)), max(1, round(oh * scale))
                img_np = cv2.resize(img_rgb, (rw, rh),
                                    interpolation=cv2.INTER_AREA)
                msk = (cv2.resize(original_mask.astype(np.float32), (rw, rh),
                                  interpolation=cv2.INTER_NEAREST_EXACT)
                       > 0).astype(np.uint8)
            else:
                rw, rh = ow, oh
                img_np = img_rgb.copy()
                msk = original_mask.astype(np.uint8)
            if rh < s or rw < s:
                img_np = cv2.copyMakeBorder(img_np, 0, s - rh, 0, s - rw,
                                            cv2.BORDER_REFLECT)
                msk = cv2.copyMakeBorder(msk, 0, s - rh, 0, s - rw,
                                         cv2.BORDER_CONSTANT, value=0)
        elif not self._fixed_size and _mx <= s:
            _tgt = max(_mx, 128)
            _sc = _tgt / _mx
            if abs(_sc - 1.0) < 1e-6:
                rw, rh = ow, oh
                img_np = img_rgb.copy()
                msk = original_mask.astype(np.uint8)
            else:
                rw, rh = max(1, round(ow * _sc)), max(1, round(oh * _sc))
                img_np = cv2.resize(img_rgb, (rw, rh), interpolation=cv2.INTER_CUBIC)
                msk = (cv2.resize(original_mask.astype(np.float32), (rw, rh),
                                  interpolation=cv2.INTER_NEAREST_EXACT) > 0).astype(np.uint8)
            _pw, _ph = (-rw) % 8, (-rh) % 8
            if _pw or _ph:
                img_np = cv2.copyMakeBorder(img_np, 0, _ph, 0, _pw, cv2.BORDER_REFLECT)
                msk = cv2.copyMakeBorder(msk, 0, _ph, 0, _pw,
                                         cv2.BORDER_CONSTANT, value=0)
        else:
            scale = s / _mx
            rw, rh = max(1, round(ow * scale)), max(1, round(oh * scale))
            interp = cv2.INTER_AREA if _mx > s else cv2.INTER_CUBIC
            img_np = cv2.resize(img_rgb, (rw, rh), interpolation=interp)

            mask_interp = cv2.INTER_AREA if scale < 1 else cv2.INTER_NEAREST_EXACT
            msk = (cv2.resize(original_mask.astype(np.float32), (rw, rh),
                              interpolation=mask_interp) > 0).astype(np.uint8)
            if self._fixed_size:
                img_np = cv2.copyMakeBorder(img_np, 0, s - rh, 0, s - rw, cv2.BORDER_REFLECT)
                msk = cv2.copyMakeBorder(msk, 0, s - rh, 0, s - rw, cv2.BORDER_REFLECT)
            else:
                _pw, _ph = (-rw) % 8, (-rh) % 8
                if _pw or _ph:
                    img_np = cv2.copyMakeBorder(img_np, 0, _ph, 0, _pw,
                                                cv2.BORDER_REFLECT)
                    msk = cv2.copyMakeBorder(msk, 0, _ph, 0, _pw,
                                             cv2.BORDER_CONSTANT, value=0)
        img_np[msk > 0] = 0
        img_in = (img_np.astype(np.float32) / 255.0).transpose(2, 0, 1)[None]
        mask_in = msk.astype(np.float32)[None, None]
        return {"img_rgb": img_rgb, "original_mask": original_mask,
                "ow": int(ow), "oh": int(oh), "rw": int(rw), "rh": int(rh),
                "img_in": img_in, "mask_in": mask_in,
                "has_mask": _has_mask}

    def _next_session(self):
        """v1.14.106 — چرخشِ round-robin بینِ سشنِ اصلی (GPU) و سشنِ CPU
        برایِ dual-device. وقتی سشنِ دوم نیست → همان سشنِ اصلی (بدونِ
        هیچ تغییرِ رفتار)."""
        _sc = getattr(self, "session_cpu", None)
        if _sc is None:
            return self.session
        try:
            with self._sess_rr_lock:
                self._sess_rr += 1
                _odd = (self._sess_rr & 1) == 1
        except Exception:
            return self.session
        return _sc if _odd else self.session

    def _run_tensors(self, img_in, mask_in):
        feeds = {self._in_image: img_in, self._in_mask: mask_in}
        _sess = self._next_session()
        try:
            return _sess.run(None, feeds)[0]
        except Exception:
            if _sess is not self.session:
                # سشنِ CPU خراب شد → سشنِ اصلی (امن)
                return self.session.run(None, feeds)[0]
            raise

    def run_batch_tensors(self, tensors):
        """v1.14.96-speed (SRV-G phase2) — یک session.run برایِ N پچِ
        «هم‌شکل» (بعدِ batch=N؛ همان پدینگ/همان ترتیب). ورودی: لیستِ
        خروجیِ _prep_sample با tensorهایِ هم‌شکل. خروجی: outِ هر نمونه به
        ترتیبِ ورودی. شکست → exception (تماس‌گیرنده per-sample می‌رود)."""
        if not tensors:
            return []
        _imgs = np.concatenate([t["img_in"] for t in tensors], axis=0)
        _msks = np.concatenate([t["mask_in"] for t in tensors], axis=0)
        _out = self._run_tensors(_imgs, _msks)
        return [_out[i] for i in range(_out.shape[0])]

    def _finish_sample(self, t, out_elem):
        """پس‌پردازشِ خروجیِ مدل برایِ «یک» نمونه — دقیقاً همان کدِ
        __call__ بعد از run (بایت‌به‌بایت)."""
        o = out_elem.transpose(1, 2, 0).astype(np.float32)
        try:
            if float(np.max(o)) > 1.5:
                o = o / 255.0
        except Exception:
            pass
        o = np.clip(o, 0.0, 1.0)
        o = (o * 255).astype(np.uint8)
        predicted = cv2.resize(o[:t["rh"], :t["rw"]], (t["ow"], t["oh"]),
                               interpolation=cv2.INTER_LANCZOS4)
        result = t["img_rgb"].copy()
        result[t["original_mask"]] = predicted[t["original_mask"]]
        return Image.fromarray(result)

    def __call__(self, image, mask):
        t = self._prep_sample(image, mask)
        if not t["has_mask"]:
            return Image.fromarray(t["img_rgb"].copy())
        out = self._run_tensors(t["img_in"], t["mask_in"])
        return self._finish_sample(t, out[0])


class LamaTorch:
    FILE = "big-lama.pt"
    FALLBACK_URL = ("https://github.com/enesmsahin/simple-lama-inpainting/"
                    "releases/download/v0.1.0/big-lama.pt")
    CPU_MAX_SIDE = 1280
    ANDROID_MAX_SIDE = 768

    def __init__(self, model_path: Optional[str] = None, prefer_gpu: bool = True,
                 cache_dir: Optional[str] = None, max_side: Optional[int] = None):
        import torch
        self._torch = torch
        self.device = torch.device(
            "cuda" if (prefer_gpu and torch.cuda.is_available()) else "cpu"
        )
        if not model_path or not os.path.isfile(model_path):
            model_path = self._download_model(cache_dir=cache_dir)
        self.model_path = model_path
        self.model = torch.jit.load(model_path, map_location=self.device)
        self.model.eval()
        if max_side is not None:
            self.max_side = int(max_side)
        elif _IS_ANDROID:
            self.max_side = self.ANDROID_MAX_SIDE
        else:
            self.max_side = None if self.device.type == "cuda" else self.CPU_MAX_SIDE
        print(
            f"[+] big-LaMa (TorchScript) آماده | device={self.device.type} | "
            f"max_side={'کامل' if not self.max_side else self.max_side}"
        )

    @classmethod
    def _download_model(cls, cache_dir: Optional[str] = None) -> str:
        env_p = os.environ.get("LAMA_MODEL")
        if env_p and os.path.isfile(env_p):
            return env_p
        m = _mirror_model(cls.FILE)
        if m:
            return m
        dst = os.path.join(_model_cache_dir("det_models"), cls.FILE)
        if os.path.isfile(dst) and os.path.getsize(dst) > 1_000_000:
            print(f"[*] مدل big-lama.pt از کش: {dst}")
            return dst
        last = None
        for url in (_RAPIDOCR_MIRROR + cls.FILE, cls.FALLBACK_URL):
            try:
                print(f"[*] دانلود مدل big-lama.pt از {url.split('/')[2]} ...")
                _dl_to(url, dst, name=cls.FILE)
                return dst
            except Exception as e:
                last = e
                print(f"    [!] دانلود از {url.split('/')[2]} نشد: {e}")
                try:
                    if os.path.isfile(dst + ".part"):
                        os.remove(dst + ".part")
                except Exception:
                    pass
        raise RuntimeError(f"دانلود big-lama.pt ناموفق: {last}")

    @staticmethod
    def _ceil_mod(x: int, mod: int) -> int:
        return x if x % mod == 0 else (x // mod + 1) * mod

    def __call__(self, image, mask):
        torch = self._torch
        if isinstance(image, np.ndarray):
            if image.ndim == 3 and image.shape[2] in (3, 4):
                img_rgb = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)
            else:
                img_rgb = cv2.cvtColor(image, cv2.COLOR_GRAY2RGB)
        else:
            img_rgb = np.array(image.convert("RGB"))
        if isinstance(mask, np.ndarray):
            if mask.ndim == 3:
                mask_u8 = mask[..., 0] if mask.shape[2] == 1 else cv2.cvtColor(mask, cv2.COLOR_BGR2GRAY)
            else:
                mask_u8 = mask
        else:
            mask_u8 = np.array(mask.convert("L"))
        if mask_u8.shape != img_rgb.shape[:2]:
            raise ValueError("Image and mask dimensions must match")
        m_full = mask_u8 > 0
        if not np.any(m_full):
            return Image.fromarray(img_rgb.copy())
        oh, ow = img_rgb.shape[:2]

        if max(oh, ow) > 2.5 * min(oh, ow):
            return self._call_banded(img_rgb, m_full)
        return self._call_single(img_rgb, m_full)

    _BAND_OVERLAP = 96

    def _call_banded(self, img_rgb: np.ndarray, m_full: np.ndarray):
        oh, ow = img_rgb.shape[:2]
        out = img_rgb.copy()
        vertical = oh >= ow
        L = oh if vertical else ow
        short = ow if vertical else oh
        band = int(max(1024, min(L, short * 2)))
        ov = self._BAND_OVERLAP
        step = max(1, band - ov)
        starts = list(range(0, L, step))
        if starts and starts[-1] + ov >= L and len(starts) > 1:
            starts.pop()
        for s in starts:
            e = min(L, s + band)
            if vertical:
                sub_img = img_rgb[s:e]
                sub_m = m_full[s:e]
            else:
                sub_img = img_rgb[:, s:e]
                sub_m = m_full[:, s:e]
            if not sub_m.any():
                continue
            res = np.array(self._call_single(sub_img, sub_m))
            core = np.zeros_like(sub_m)
            a = 0 if s == 0 else ov // 2
            b = (e - s) if e == L else (e - s) - ov // 2
            if a >= b:
                a, b = 0, e - s
            if vertical:
                core[a:b, :] = True
            else:
                core[:, a:b] = True
            take = sub_m & core
            if not take.any():
                continue
            if vertical:
                out[s:e][take] = res[take]
            else:
                out[:, s:e][take] = res[take]
        return Image.fromarray(out)

    def _call_single(self, img_rgb: np.ndarray, m_full: np.ndarray):
        torch = self._torch
        oh, ow = img_rgb.shape[:2]

        scale = 1.0
        if self.max_side and max(oh, ow) > self.max_side:
            scale = self.max_side / float(max(oh, ow))
        rw, rh = max(8, int(round(ow * scale))), max(8, int(round(oh * scale)))
        if scale != 1.0:
            interp = cv2.INTER_AREA if scale < 1 else cv2.INTER_CUBIC
            img_np = cv2.resize(img_rgb, (rw, rh), interpolation=interp)
            m0 = cv2.resize(m_full.astype(np.uint8), (rw, rh),
                            interpolation=cv2.INTER_NEAREST) > 0
        else:
            img_np = img_rgb
            m0 = m_full

        ph, pw = self._ceil_mod(rh, 8), self._ceil_mod(rw, 8)
        if (ph, pw) != (rh, rw):
            img_p = np.pad(img_np, ((0, ph - rh), (0, pw - rw), (0, 0)), mode="symmetric")
            msk_p = np.pad(m0.astype(np.float32), ((0, ph - rh), (0, pw - rw)), mode="symmetric")
        else:
            img_p = img_np
            msk_p = m0.astype(np.float32)

        x = torch.from_numpy(np.ascontiguousarray(img_p.astype(np.float32) / 255.0)) \
                 .permute(2, 0, 1)[None].to(self.device)
        mk = torch.from_numpy((msk_p > 0).astype(np.float32))[None, None].to(self.device)
        with torch.inference_mode():
            out = self.model(x, mk)
        res = out[0].permute(1, 2, 0).detach().float().cpu().numpy()
        res = np.clip(res * 255, 0, 255).astype(np.uint8)[:rh, :rw]

        if scale != 1.0:
            res = cv2.resize(res, (ow, oh), interpolation=cv2.INTER_LANCZOS4)
        result = img_rgb.copy()
        result[m_full] = res[m_full]
        return Image.fromarray(result)


class RTDetrV2ONNXDetector:

    DET_REPO = "ogkalu/comic-text-and-bubble-detector"
    DET_FILES = ("detector-v4-s_int8.onnx", "detector.onnx", "detector-v4.onnx")
    CLASS_NAMES = {0: "bubble", 1: "text_bubble", 2: "text_free"}
    INPUT_SIZE = 640
    MAX_DETS = 120

    def __init__(
        self,
        model_path: Optional[str] = None,
        prefer_gpu: bool = True,
        conf_thresh: float = 0.35,
        iou_thresh: float = 0.40,
        threads: int = 4,
        multi_scale: bool = False,
        cache_dir: Optional[str] = None,
    ):
        self.conf_thresh = conf_thresh
        self.iou_thresh = iou_thresh
        self.multi_scale = multi_scale
        self.INPUT_SIZE = 640

        if not model_path or not os.path.isfile(model_path) or os.path.getsize(model_path) < 1000:
            model_path = None
            last_err = None

            def _hf_with_timeout(fname: str):
                if hf_hub_download is None:
                    raise RuntimeError("huggingface_hub لازم است")
                import concurrent.futures as _cf
                with _cf.ThreadPoolExecutor(max_workers=1) as _ex:
                    fut = _ex.submit(
                        hf_hub_download, repo_id=self.DET_REPO,
                        filename=fname, cache_dir=cache_dir,
                    )
                    try:
                        return fut.result(timeout=240)
                    except _cf.TimeoutError:
                        raise RuntimeError("huggingface: تایم‌اوت ۲۴۰s (در ایران قطع است)") from None

            _forced = (os.environ.get("MANGA_DET_MODEL") or "").strip()
            files = list(self.DET_FILES)
            if _forced:
                _fb = os.path.basename(_forced)
                files = [_fb] + [f for f in files if f != _fb]

            self.session = None
            for fname in files:
                cand = None
                try:
                    if _forced and fname == os.path.basename(_forced) \
                            and os.path.isfile(_forced):
                        cand = _forced
                    if cand is None:
                        cand = _mirror_model(fname)
                    if not cand:
                        print(f"[*] دانلود مدل RT-DETR ONNX از {self.DET_REPO}/{fname} ...")
                        cand = _hf_with_timeout(fname)
                    if not (cand and os.path.isfile(cand) and os.path.getsize(cand) > 1000):
                        print(f"    [!] {fname} خالی/ناقص بود → دانلود مستقیم...")
                        url = f"https://huggingface.co/{self.DET_REPO}/resolve/main/{fname}"
                        dest = os.path.join(
                            cache_dir or _model_cache_dir("det_models"), fname)
                        os.makedirs(os.path.dirname(dest) or ".", exist_ok=True)
                        _dl_to(url, dest, name=fname)
                        if os.path.isfile(dest) and os.path.getsize(dest) > 1000:
                            cand = dest
                    if not cand:
                        continue
                    try:
                        _sess = _make_ort_session(
                            cand, prefer_gpu=prefer_gpu, threads=threads,
                            ep=_resolve_lama_ep(), ep_ab=_is_auto_ep())
                    except Exception as _se:
                        print(f"    [!] {fname} سشن ONNX نساخت ({_se}) → فایل بعدی")
                        try:
                            if os.path.isfile(cand) and cand.endswith(".onnx"):
                                os.remove(cand)
                        except Exception:
                            pass
                        continue
                    model_path, self.session = cand, _sess
                    break
                except Exception as e:
                    last_err = e
                    print(f"    [!] {fname} پیدا نشد: {e}")
            if not (model_path and self.session):
                raise RuntimeError(
                    f"نتوانست مدل RT-DETR را از {self.DET_REPO} دانلود کند: {last_err}"
                )
        else:
            self.session = _make_ort_session(
                model_path, prefer_gpu=prefer_gpu, threads=threads,
                ep=_resolve_lama_ep(), ep_ab=_is_auto_ep())

        self.model_path = model_path
        try:
            print(f"[+] مدل تشخیص حباب: {os.path.basename(self.model_path)}")
        except Exception:
            pass
        in_names = [i.name for i in self.session.get_inputs()]
        self._in_images = "images" if "images" in in_names else in_names[0]
        self._in_sizes = "orig_target_sizes" if "orig_target_sizes" in in_names else (
            in_names[1] if len(in_names) > 1 else None
        )

    def _preprocess(self, image_bgr: np.ndarray):
        h0, w0 = image_bgr.shape[:2]
        rgb = cv2.cvtColor(image_bgr, cv2.COLOR_BGR2RGB)
        resized = cv2.resize(rgb, (self.INPUT_SIZE, self.INPUT_SIZE), interpolation=cv2.INTER_LINEAR)
        arr = resized.astype(np.float32) / 255.0
        arr = arr.transpose(2, 0, 1)[None]
        orig_size = np.array([[w0, h0]], dtype=np.int64)
        return arr, orig_size, h0, w0

    def _parse_outputs(self, outputs, h0: int, w0: int, threshold: float) -> List[dict]:
        if not outputs or len(outputs) < 3:
            return []

        def _squeeze(a):
            a = np.asarray(a)
            if a.ndim >= 2 and a.shape[0] == 1:
                a = a[0]
            return a

        labels = _squeeze(outputs[0])
        boxes = _squeeze(outputs[1])
        scores = _squeeze(outputs[2])
        if scores.ndim == 1 and labels.ndim == 1 and boxes.ndim == 2:
            pass
        elif boxes.ndim == 1:
            labels, boxes, scores = _squeeze(outputs[1]), _squeeze(outputs[0]), _squeeze(outputs[2])

        raw: List[dict] = []
        n = min(len(labels), len(boxes), len(scores))
        for i in range(n):
            conf = float(scores[i])
            if conf < float(threshold):
                continue
            lab = int(labels[i])
            name = self.CLASS_NAMES.get(lab, "text_bubble")
            if name == "bubble":
                if conf < 0.48:
                    continue
                name = "text_bubble"
            box = boxes[i]
            if len(box) < 4:
                continue
            x1, y1, x2, y2 = [float(v) for v in box[:4]]
            if 0.0 <= x1 <= 1.5 and 0.0 <= x2 <= 1.5 and x2 <= 2.0:
                x1, x2 = x1 * w0, x2 * w0
                y1, y2 = y1 * h0, y2 * h0
            x1 = int(max(0, min(w0 - 1, round(x1))))
            y1 = int(max(0, min(h0 - 1, round(y1))))
            x2 = int(max(0, min(w0, round(x2))))
            y2 = int(max(0, min(h0, round(y2))))
            if x2 - x1 < 12 or y2 - y1 < 12:
                continue
            bw, bh = x2 - x1, y2 - y1
            if bw * bh < 400:
                continue
            ar = bw / max(1, bh)
            if 0.75 <= ar <= 1.35:
                shape = "circle"
            elif ar > 1.6 or ar < 0.55:
                shape = "box"
            else:
                shape = "round"
            raw.append({
                "class_id": lab,
                "class_name": name,
                "confidence": conf,
                "rect": [x1, y1, x2, y2],
                "shape_type": shape,
                "mask_poly": None,
            })
        return self._nms(raw, self.iou_thresh)

    @staticmethod
    def _nms(boxes, iou_thresh: float):
        if not boxes:
            return []

        def iou(a, b):
            xA = max(a[0], b[0]); yA = max(a[1], b[1])
            xB = min(a[2], b[2]); yB = min(a[3], b[3])
            inter = max(0, xB - xA) * max(0, yB - yA)
            if inter == 0:
                return 0.0
            areaA = (a[2] - a[0]) * (a[3] - a[1])
            areaB = (b[2] - b[0]) * (b[3] - b[1])
            return inter / float(areaA + areaB - inter)

        priority = {"text_bubble": 2, "text_free": 1, "bubble": 0}
        boxes = sorted(
            boxes,
            key=lambda x: (priority.get(x["class_name"], 0), x["confidence"]),
            reverse=True,
        )
        keep, pool = [], list(boxes)
        while pool:
            best = pool.pop(0)
            keep.append(best)
            pool = [b for b in pool if iou(best["rect"], b["rect"]) < iou_thresh]
        return keep[: RTDetrV2ONNXDetector.MAX_DETS]

    def _detect_single(self, image_bgr: np.ndarray, threshold: float):
        im_data, orig_size, h0, w0 = self._preprocess(image_bgr)
        feeds = {self._in_images: im_data}
        if self._in_sizes is not None:
            feeds[self._in_sizes] = orig_size
        outputs = self.session.run(None, feeds)
        return self._parse_outputs(outputs, h0, w0, threshold)


    TILE_HEIGHT = 1680
    TILE_OVERLAP = 520
    TILE_MIN_GAIN = 1.25

    def detect(self, image_bgr: np.ndarray, fast: bool = False):
        # fast=True → فقط یک مقیاس (بدون پاس دوم multi_scale) — برای برش امن
        # که فقط محل حباب‌ها را می‌خواهد؛ ~۲× سریع‌تر روی CPU.
        h = int(image_bgr.shape[0])
        if h > int(self.TILE_HEIGHT * self.TILE_MIN_GAIN):
            return self._detect_tiled(image_bgr, fast=fast)
        return self._detect_plain(image_bgr, fast=fast)

    def _detect_tiled(self, image_bgr: np.ndarray, fast: bool = False):
        h, w = image_bgr.shape[:2]
        tile_h = int(self.TILE_HEIGHT)
        overlap = int(self.TILE_OVERLAP)
        step = max(500, tile_h - overlap)

        tiles = []
        core_start = 0
        while core_start < h:
            core_end = min(core_start + tile_h, h)
            ys = max(0, core_start - (overlap if core_start > 0 else 0))
            ye = min(h, core_end + (overlap if core_end < h else 0))
            tiles.append((core_start, core_end, ys, ye))
            if core_end >= h:
                break
            core_start += step

        _tw = 1
        try:
            if len(tiles) > 1:
                if _on_android():
                    _tw = 2
                else:
                    _tw = max(2, min(3, (os.cpu_count() or 2) // 2))
        except Exception:
            _tw = 1
        _tw = max(1, min(_tw, len(tiles)))
        if _tw > 1:
            with ThreadPoolExecutor(max_workers=_tw) as _dex:
                _results = list(_dex.map(
                    lambda _t: self._detect_plain(_t, fast=fast),
                    [image_bgr[ys:ye] for (_cs, _ce, ys, ye) in tiles]))
        else:
            _results = [self._detect_plain(image_bgr[ys:ye], fast=fast)
                        for (_cs, _ce, ys, ye) in tiles]

        all_boxes: List[dict] = []
        for (core_start, core_end, ys, ye), tile_boxes in zip(tiles, _results):
            for b in tile_boxes:
                x1, y1, x2, y2 = b["rect"]
                cy = ys + (y1 + y2) / 2.0
                margin = overlap * 0.35
                if (core_start - margin) <= cy < (core_end + margin):
                    nb = dict(b)
                    nb["rect"] = [x1, y1 + ys, x2, y2 + ys]
                    all_boxes.append(nb)

        merged = self._nms(all_boxes, max(0.40, self.iou_thresh))
        return MangaTranslator._drop_contained_boxes(merged, contain_thresh=0.65)


    def _detect_plain(self, image_bgr: np.ndarray, fast: bool = False):
        h, w = image_bgr.shape[:2]
        page_area = float(max(1, h * w))

        low_th = max(0.28, self.conf_thresh * 0.75)
        all_boxes = []
        for b in self._detect_single(image_bgr, low_th):
            x1, y1, x2, y2 = b["rect"]
            bw, bh = x2 - x1, y2 - y1
            area = bw * bh
            if b["confidence"] >= self.conf_thresh:
                all_boxes.append(b)
                continue

            if (area < page_area * 0.03 and bw < w * 0.30 and bh < h * 0.22
                    and b["confidence"] >= low_th + 0.04):
                all_boxes.append(b)

        if self.multi_scale and not fast and h >= 1100 and w >= 500:
            sw = max(1, int(w * 0.55))
            sh = max(1, int(h * 0.55))
            if sw >= 280 and sh >= 280:
                small = cv2.resize(image_bgr, (sw, sh), interpolation=cv2.INTER_AREA)
                low_th2 = max(0.30, self.conf_thresh * 0.85)
                inv = 1.0 / 0.55
                for b in self._detect_single(small, low_th2):
                    x1, y1, x2, y2 = b["rect"]
                    b["rect"] = [int(x1 * inv), int(y1 * inv), int(x2 * inv), int(y2 * inv)]
                    bw = b["rect"][2] - b["rect"][0]
                    bh = b["rect"][3] - b["rect"][1]
                    area = bw * bh
                    if (area < page_area * 0.03 and max(bw, bh) < max(w, h) * 0.30
                            and b["confidence"] >= low_th2):
                        all_boxes.append(b)

        cleaned = self._nms(all_boxes, max(0.42, self.iou_thresh))
        return MangaTranslator._drop_contained_boxes(cleaned, contain_thresh=0.68)


# v1.14.96-speed — منبعِ اصلیِ مدل‌هایِ OCR = ریلیزِ «models» رویِ GitHub
# (همان amirwolf512k/Manga-AutoTranslate)؛ assetsها دقیقاً با همین نام‌ها
# آنجاست: PP-OCRv6_det_small.onnx (det) / PP-OCRv6_rec_small.onnx (rec
# en+ch) / korean_PP-OCRv5_rec_mobile.onnx / japan_PP-OCRv4_rec_mobile.onnx
# v1.14.152 — مجموعهٔ K3 اضافه شد (درخواست: «از همین نسخه که k3 استفاده
# میکنه استفاده کن»): PP-OCRv6_medium_det_onnx.onnx (59.16MiB) /
# PP-OCRv6_medium_rec_onnx.onnx (73.01MiB) / PP-OCRv5_korean_rec.onnx
# (12.80MiB) = عینِ فایلهایِ رسمیِ PaddlePaddle رویِ HuggingFace که خودِ
# K3 دانلود میکند (حجمها مو به مو با پوشهٔ K3) + ch_PP-OCRv4_det_infer
# .onnx (4.53MiB) + ch_PP-OCRv4_rec_infer.onnx (10.35MiB؛ dict داخلیِ
# metadata = ppocr_keys_v1 با 6623 کاراکتر).
# / ch_ppocr_mobile_v2.0_cls_mobile.onnx (cls — در رانِ عادی استفاده
# نمی‌شود). مسیرِ دوم فقط فال‌بکِ قطعِ گیت‌هاب است (modelscope).
_RAPIDOCR_MIRROR = ("https://github.com/amirwolf512k/Manga-AutoTranslate/"
                    "releases/download/models/")
_RAPIDOCR_MS = ("https://www.modelscope.cn/models/RapidAI/RapidOCR/"
                "resolve/v3.9.2/onnx")
_RAPIDOCR_FILES = {
    "PP-OCRv6_det_small.onnx":
        _RAPIDOCR_MS + "/PP-OCRv6/det/PP-OCRv6_det_small.onnx",
    "PP-OCRv6_rec_small.onnx":
        _RAPIDOCR_MS + "/PP-OCRv6/rec/PP-OCRv6_rec_small.onnx",
    "ch_ppocr_mobile_v2.0_cls_mobile.onnx":
        _RAPIDOCR_MS + "/PP-OCRv4/cls/ch_ppocr_mobile_v2.0_cls_mobile.onnx",
    "korean_PP-OCRv5_rec_mobile.onnx":
        _RAPIDOCR_MS + "/PP-OCRv5/rec/korean_PP-OCRv5_rec_mobile.onnx",
    "japan_PP-OCRv4_rec_mobile.onnx":
        _RAPIDOCR_MS + "/PP-OCRv4/rec/japan_PP-OCRv4_rec_mobile.onnx",
    # v1.14.152 — مجموعهٔ K3 (منبعِ فالبک = رسمیِ PaddlePaddle/modelscope؛
    # منبعِ اصلی = ریلیزِ «models» خودمان با همین نامها)
    "PP-OCRv6_medium_det_onnx.onnx":
        "https://huggingface.co/PaddlePaddle/PP-OCRv6_medium_det_onnx"
        "/resolve/main/inference.onnx",
    "PP-OCRv6_medium_rec_onnx.onnx":
        "https://huggingface.co/PaddlePaddle/PP-OCRv6_medium_rec_onnx"
        "/resolve/main/inference.onnx",
    "PP-OCRv5_korean_rec.onnx":
        "https://huggingface.co/PaddlePaddle/korean_PP-OCRv5_mobile_rec_onnx"
        "/resolve/main/inference.onnx",
    "ch_PP-OCRv4_det_infer.onnx":
        _RAPIDOCR_MS + "/PP-OCRv4/det/ch_PP-OCRv4_det_mobile.onnx",
    "ch_PP-OCRv4_rec_infer.onnx":
        _RAPIDOCR_MS + "/PP-OCRv4/rec/ch_PP-OCRv4_rec_mobile.onnx",
    # v1.14.179 — موتورِ «فلاتر-پدل» (flutter-paddle-ocr) = PP-OCRv6 tiny
    # (دستورِ سازنده: «flutter-paddle-ocr اینم اضافه کن واسه تست» —
    # github.com/mencomao/flutter-paddle-ocr همان PP-OCRv6 tinyِ ONNXِ
    # خالص رویِ ONNX Runtime است، نه Paddle-Lite). منبعِ اصلی = HFِ
    # رسمیِ PaddlePaddle (همان الگویِ medium)؛ فالبک = ریلیزِ modelsِ
    # خودمان. det 1.7MB + rec 4.3MB — سبکترین جفتِ خانوادهٔ v6.
    "PP-OCRv6_tiny_det.onnx":
        "https://huggingface.co/PaddlePaddle/PP-OCRv6_tiny_det_onnx"
        "/resolve/main/inference.onnx",
    "PP-OCRv6_tiny_rec.onnx":
        "https://huggingface.co/PaddlePaddle/PP-OCRv6_tiny_rec_onnx"
        "/resolve/main/inference.onnx",
    # dictِ مخصوصِ tiny (۶۹۰۴ نویسه — استخراجشده از inference.ymlِ مدلِ
    # رسمی؛ جدا از medium ۱۸۷۰۷ی و small ۶۶۲۳ی) — فقط از ریلیزِ خودمان
    "ppocr_keys_v6_tiny_utf8.txt":
        _RAPIDOCR_MIRROR + "ppocr_keys_v6_tiny_utf8.txt",
    # v1.14.182 — charsetِ رسمیِ PP-OCRv6 medium rec (paddleocr.aiِ
    # android_deployment: «rec = inference.onnx + inference.yml»)؛
    # ۱۸۷۰۸ نویسه + فاصله. v1.14.184 — پلِ PaddleOcrBridge از
    # inference.ymlِ باندلشده در assets میخواند (SDKِ رسمی) — این مدخل
    # فقط برایِ سازگاریِ نگاشتِ URLهایِ قدیمی مانده است.
    "PP-OCRv6_medium_rec_inference.yml":
        "https://huggingface.co/PaddlePaddle/PP-OCRv6_medium_rec_onnx"
        "/resolve/main/inference.yml",
}


def _rapidocr_model_pair(lang: str, small: bool = False,
                         tiny: bool = False):
    """v1.14.152 — جفتِ (det, rec) بر اساسِ زبان.

    پیشفرض = مجموعهٔ K3 (دقیقاً همان ۵ فایلِ پوشهٔ K3):
      det = PP-OCRv6_medium_det_onnx.onnx (رسمیِ PaddlePaddle، 59.16MiB)
      recِ en/سایر = PP-OCRv6_medium_rec_onnx.onnx (73.01MiB)
      recِ ko = PP-OCRv5_korean_rec.onnx (رسمی، 12.80MiB)
      zh = جفتِ کاملِ ch_PP-OCRv4 (det 4.53MiB + rec 10.35MiB)
      ja = japan_PP-OCRv4_rec_mobile قبلی (K3 برایِ ژاپنی encoder-decoder
           جداگانه دارد — خارج از scopeِ این تغییر)
    small=True (فقط شبیهسازِ x86_64 در CI) = مجموعهٔ سبکِ قبلی تا
    بودجهٔ زمانی و گیتهایِ CI دستنخورده بمانند.
    v1.14.179 — tiny=True = «فلاتر-پدل»: PP-OCRv6_tiny det (1.7MB) +
    PP-OCRv6_tiny_rec (4.3MB؛ dictِ ۶۹۰۴یِ خودش) — سبکترین جفت؛
    ja/ko با recِ موبایلِ خودشان میمانند (tiny فقط لاتین/CHS است).
    """
    _low = str(lang).lower()
    if tiny:
        _det = "PP-OCRv6_tiny_det.onnx"
        if _low in ("korean", "ko"):
            return _det, "korean_PP-OCRv5_rec_mobile.onnx"
        if _low in ("japan", "ja", "japanese"):
            return _det, "japan_PP-OCRv4_rec_mobile.onnx"
        return _det, "PP-OCRv6_tiny_rec.onnx"
    if small:
        _det = "PP-OCRv6_det_small.onnx"
        if _low in ("korean", "ko"):
            return _det, "korean_PP-OCRv5_rec_mobile.onnx"
        if _low in ("japan", "ja", "japanese"):
            return _det, "japan_PP-OCRv4_rec_mobile.onnx"
        return _det, "PP-OCRv6_rec_small.onnx"
    if _low in ("ch", "zh", "chinese", "ch_sim", "chinese_cht"):
        return "ch_PP-OCRv4_det_infer.onnx", "ch_PP-OCRv4_rec_infer.onnx"
    _det = "PP-OCRv6_medium_det_onnx.onnx"
    if _low in ("korean", "ko"):
        return _det, "PP-OCRv5_korean_rec.onnx"
    if _low in ("japan", "ja", "japanese"):
        return _det, "japan_PP-OCRv4_rec_mobile.onnx"
    return _det, "PP-OCRv6_medium_rec_onnx.onnx"


def _fmt_mb(n: float) -> str:
    return f"{n / (1024 * 1024):.1f}MB"


def _dl_progress(name: str, done: int, total: int, _last: list = [0.0, 0]) -> None:
    import time as _t
    now = _t.time()
    if total > 0:
        pct = min(100, int(done * 100 / total))
        if now - _last[0] < 0.8 and pct - _last[1] < 5 and pct < 100:
            return
        _last[0], _last[1] = now, pct
        print(f"\r    دانلود {name}: {pct}% ({_fmt_mb(done)}/{_fmt_mb(total)})"
              + (" " * 4), end="", flush=True)
    else:
        if now - _last[0] < 1.5:
            return
        _last[0] = now
        print(f"\r    دانلود {name}: {_fmt_mb(done)}", end="", flush=True)


def _dl_to(url, dst, name: str = ""):
    import time as _t
    import urllib.request
    if not name:
        name = os.path.basename(dst)
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    t0 = _t.time()
    with urllib.request.urlopen(req, timeout=900) as r, \
            open(dst + ".part", "wb") as f:
        total = int(r.headers.get("Content-Length") or 0)
        done = 0
        while True:
            chunk = r.read(1 << 20)
            if not chunk:
                break
            f.write(chunk)
            done += len(chunk)
            _dl_progress(name, done, total)
    if total and done < total:
        raise RuntimeError(f"ناقص: {done}/{total} بایت")
    if os.path.getsize(dst + ".part") > 1000:
        dt = _t.time() - t0
        print(f"\r    ✔ {name}: {_fmt_mb(done)} در {dt:.0f}s" + " " * 8)
        os.replace(dst + ".part", dst)
        return dst
    raise RuntimeError("فایل ناقص")


def _model_cache_dir(sub):
    d = os.path.join(os.environ.get("MANGA_FILES_DIR") or os.getcwd(), sub)
    try:
        os.makedirs(d, exist_ok=True)
    except Exception:
        pass
    return d


def _mirror_model(fname):
    loc = os.path.join(_model_cache_dir("det_models"), fname)
    if os.path.isfile(loc) and os.path.getsize(loc) > 1000:
        return loc
    try:
        print(f"    [mirror] {fname} ...")
        _dl_to(_RAPIDOCR_MIRROR + fname, loc)
        return loc
    except Exception as e:
        print(f"    [!] mirror نشد: {e}")
        try:
            if os.path.isfile(loc + ".part"):
                os.remove(loc + ".part")
        except Exception:
            pass
        return None


def _android_heal_model_dir(mdir, quiet=False):
    """v1.14.154 — درمانِ EACCES («system error number 13») مدلها رویِ گوشی.

    ریشه: بعد از بهروزرسانیِ اپ/بازیابیِ بکاپ، مجوزِ خواندنِ فایلِ مدلِ
    دانلودشده از ONNX Runtime گرفته میشود → «PP-OCRv6 … failed: system
    error number 13» → استخراجِ بیصدا خالی میماند (شکایتِ «استخراج
    نمیکند»). درمان: chmodِ 0o644 همهٔ فایلهایِ
    پوشهٔ مدل؛ فایلِ هنوزناخوانا → حذف (تا _ensure دوباره دانلود کند).
    فقط اندروید (گیتِ MANGA_MODEL_HEAL) — PC بیت‌به‌بیت دستنخورده."""
    try:
        if not mdir or not os.path.isdir(mdir):
            return
        if not _android_gate("MANGA_MODEL_HEAL"):
            return
        _n_heal = 0
        for _fn in sorted(os.listdir(mdir)):
            _fp = os.path.join(mdir, _fn)
            if not os.path.isfile(_fp):
                continue
            try:
                os.chmod(_fp, 0o644)
            except Exception:
                pass
            try:
                with open(_fp, "rb") as _f:
                    _f.read(64)
            except PermissionError:
                try:
                    os.remove(_fp)
                    _n_heal += 1
                except Exception:
                    pass
            except Exception:
                pass
        if _n_heal and not quiet:
            print(f"[*] {_n_heal} فایلِ مدلِ ناخوانا (EACCES) حذف شد "
                  "→ دانلودِ دوباره")
    except Exception:
        pass


# v1.14.162 — قفلِ تک‌نمونهٔ دانلودِ هر فایل: دو ورکرِ همزمان که همان
# فایلِ مدل را میخواهند، هر دو «همان فایل را دانلود میکردند»؛ یکی تمام
# میشد و .part را rename میکرد، دومی وسطِ نوشتن/rename با «[Errno 2] No such
# file or directory … .part» میرفت و لاگِ «دانلود ناموفق — اینترنت/VPN
# را چک کن» میداد در حالیکه فایل سالم بود. حالا هر فایل قفلِ خودش را
# دارد؛ نفرِ دوم منتظر میماند و بعد داخلِ قفل «از قبل هست» را میبیند.
_DL_FILE_LOCKS: Dict[str, threading.Lock] = {}
_DL_FILE_LOCKS_GUARD = threading.Lock()


def _dl_file_lock(dst: str) -> threading.Lock:
    with _DL_FILE_LOCKS_GUARD:
        lk = _DL_FILE_LOCKS.get(dst)
        if lk is None:
            lk = threading.Lock()
            _DL_FILE_LOCKS[dst] = lk
        return lk


def _ensure_rapidocr_models(mdir, files=None):
    wanted = files or list(_RAPIDOCR_FILES)
    for fname in wanted:
        dst = os.path.join(mdir, fname)
        # v1.14.152 — فایلهایِ dict (txt) کوچکاند (47-75KB)؛ آستانهٔ
        # 100KB فقط برایِ مدلهاست وگرنه dict هر بار دوباره دانلود میشد.
        _min_sz = 100 if fname.endswith(".txt") else 100_000
        if os.path.isfile(dst) and os.path.getsize(dst) > _min_sz:
            continue
        done = False
        _lk = _dl_file_lock(dst)
        with _lk:
            # داخلِ قفلِ همان فایل دوباره چک کن — شاید ورکرِ دیگر همین
            # حالا آن را دانلود کرده باشد (ریشهٔ ارورِ .part)
            if os.path.isfile(dst) and os.path.getsize(dst) > _min_sz:
                continue
            for url in (_RAPIDOCR_MIRROR + fname, _RAPIDOCR_FILES.get(fname)):
                if not url:
                    continue
                try:
                    print(f"  دانلود {fname} ...")
                    _dl_to(url, dst, name=fname)
                    done = True
                    break
                except Exception as e:
                    # اگر ورکرِ دیگر فایل را تمام کرده، این شکست نیست
                    if os.path.isfile(dst) and os.path.getsize(dst) > _min_sz:
                        done = True
                        break
                    host = url.split("/")[2] if url else "?"
                    print(f"  [!] {fname} از {host} نشد: {e}")
            if not done:
                print(f"  [!] دانلود {fname} ناموفق — اینترنت/VPN را چک کن")
            try:
                if os.path.isfile(dst + ".part"):
                    os.remove(dst + ".part")
            except Exception:
                pass


def _cjk_dominant_154(t: str) -> bool:
    """v1.14.154 — «بعد فارسی بحرف چرا چینی میحرفی» — ریشهٔ واقعی:
    dictِ PP-OCRv6 medium (ppocrv6_chars.txt) = ۱۸۷۰۷ نویسه که ۱۵۷۴۵
    تایش CJK است و فقط ۵۲ تا لاتین؛ با ocr_lang=en رویِ متنِ استایل‌دار،
    argmax میافتد رویِ نویسههایِ CJK → خطِ «انگلیسی» پر از 汉字 میشود
    (ML Kitِ لاتین هرگز نمیساخت). True = خطِ با غلبهٔ CJK → حذف.
    فقط برایِ زبانِ لاتین صدا زده میشود؛ خاموشی: MANGA_CJK_GUARD=0."""
    try:
        _cjk = 0
        _lat = 0
        for _c in t:
            if "\u2e80" <= _c <= "\u9fff" or "\uf900" <= _c <= "\ufaff" \
                    or "\uff00" <= _c <= "\uffef":
                _cjk += 1
            elif _c.isascii() and _c.isalpha():
                _lat += 1
        if _cjk == 0:
            return False
        return _cjk >= max(2, _lat)
    except Exception:
        return False


# ═══════════════════════════════════════════════════════════════════════
# v1.14.184 — موتورِ OCRِ گوشی = SDKِ رسمیِ PaddleOCR اندروید (تنها روش).
# دستورِ سازنده: «استفاده نکرد از onnx استخراج نزد هرروشی تو و گوشی واسه
# استخراج شده حذف کن فقط از همین لینک بالا استفاده کنه» — لینکِ رسمی:
#   paddleocr.ai/…/version3.x/inference_deployment/cross_platform/
#   android_deployment.html
# یعنی: پرتِ دستیِ ONNXِ نسخهٔ 182/183 (که رویِ گوشی هیچ متنی برنگرداند)
# و همهٔ موتورهایِ دیگرِ گوشی (پدلِ ONNXِ medium، رپیدِ small،
# فلاتر-پدلِ tiny) حذف شدند. استخراج = ماژولِ رسمیِ «ppocr-sdk» که
# بیت‌به‌بیت از PaddleOCR/deploy/ppocr-android وندور شده (کدِ
# com.paddle.ocr دست نخورده) + مدلهایِ رسمیِ PP-OCRv6_small باندلشده
# در assetsِ APK.
#   • استخراج فقط رویِ «کراپهایِ detector-v4-s_int8.onnx» صدا زده میشود
#     (همان مسیرِ _ocr_crop → RapidOCRBackend.ocr → self._mobile.ocr)
#     — هیچ پاسِ تمامصفحهای نیست (دستورِ همیشگیِ سازنده).
#   • SDKِ رسمی رویِ هر کراپ det+recِ کامل اجرا میکند: DetPreprocessor →
#     DBPostProcessor → QuadTextCrop → RecPreprocessor → CTCDecoder.
#   • قراردادِ خروجی = سطرِ META|lang|n + سطرهایِ ang|conf|box|text|blk
#     (همان قراردادِ همیشه) — پارسرِ مشترک بدونِ تغییر.
# ═══════════════════════════════════════════════════════════════════════

_MOBILE_LANG_MAP = {
    "en": "latin", "latin": "latin", "english": "latin", "fa": "latin",
    "korean": "ko", "ko": "ko",
    "japan": "ja", "ja": "ja", "japanese": "ja",
    "ch": "zh", "zh": "zh", "chinese": "zh", "ch_sim": "zh",
    "zh_hans": "zh", "zh_hant": "zh", "zh-tw": "zh", "zh_tw": "zh",
}


def _mobile_lang(lang):
    """نرمالسازیِ زبان برایِ سطرِ METAِ موتورِ گوشی."""
    return _MOBILE_LANG_MAP.get(str(lang or "en").lower(), "latin")


# ═══════════════════════════════════════════════════════════════════
# v1.14.184 — موتورِ OCRِ کراپ = SDKِ رسمیِ PaddleOCR اندروید
# (ppocr-sdkِ وندورشده — deploy/ppocr-android). دستورِ سازنده: «هرروشی
# تو گوشی واسه استخراج شده حذف کن فقط از همین لینک بالا استفاده کنه»
# (paddleocr.ai …/android_deployment.html) + دستورِ قبلی: «اول
# detector-v4-s همه قسمت هایِ متن پیدا کنه فقط همون قسمت ها استخراج
# کنه تا سریعتر باشه». پلِ Kotlin = PaddleOcrBridge (پلِ نازک رویِ
# SDKِ رسمی) با قراردادِ سطرهایِ META
# (META|lang|n + ang|conf|box|text|blk) تا پارسرِ مشترک کار کند.
# مدلها = رسمیِ PP-OCRv6_small: det (9.9MB) + rec (21.2MB) +
# inference.yml (charset) — باندلشده در assetsِ APK؛ هیچ دانلودِ
# زمانِ اجرایی نیست. فالبکی نیست؛ خطایِ موتور = خروجیِ خالیِ همان کراپ.
# ═══════════════════════════════════════════════════════════════════
_PAD_STATS = {"ms": 0.0, "n": 0, "lines": 0}


def _pad_stats_note(t0, nlines):
    try:
        _PAD_STATS["ms"] += (time.time() - t0) * 1000.0
        _PAD_STATS["n"] += 1
        _PAD_STATS["lines"] += int(nlines or 0)
        if _PAD_STATS["n"] % 8 == 0:
            print(f"[⚡] پدلِ اندروید: {_PAD_STATS['n']} OCR | "
                  f"مجموعِ {_PAD_STATS['ms'] / 1000.0:.1f}s | "
                  f"میانگینِ {_PAD_STATS['ms'] / max(1, _PAD_STATS['n']):.0f}ms | "
                  f"{_PAD_STATS['lines']} خط")
    except Exception:
        pass


class PaddleAndroidOCR:
    """OCRِ کراپ با موتورِ رسمیِ PP-OCRِ اندروید (پرتِ ppocr-android —
    v1.14.182). det (PP-OCRv6 medium) → DBPostProcessِ رسمی → کراپِ
    پرسپکتیو → rec (PP-OCRv6 medium، بچِ پدشده) → CTC با charsetِ
    inference.yml. خروجی: [ [[box, (text, score)], ...] ] — هم‌قالبِ
    RapidOcrMobile. crop_mode فقط برایِ هم‌امضایی."""

    def __init__(self, lang: str = "en"):
        try:
            from java import jclass
            self._bridge = jclass(
                "com.amirwolf.mangatranslator.PaddleOcrBridge")
        except Exception as e:
            raise RuntimeError(
                "پلِ PaddleOcrBridge در APKِ نصب‌شده نیست — APKِ جدید "
                "(v1.14.184+) را نصب کن: " + str(e)[:90])
        self.lang = _mobile_lang(lang)
        self.debug = True
        # v1.14.184 — مدلها (PP-OCRv6_small det/rec + inference.yml) در
        # assetsِ APK باندلند (assets/models/{det,rec}) — هیچ دانلودی
        # وجود ندارد؛ SDKِ رسمی از context.assets میخواند.
        try:
            _cpu_n = os.cpu_count() or 4
        except Exception:
            _cpu_n = 4
        _intra = 4 if _cpu_n > 4 else 2
        try:
            _env_th = int(os.environ.get("MANGA_OCR_THREADS", "0") or 0)
            if _env_th > 0:
                _intra = _env_th
        except Exception:
            pass
        if not self._bridge.init(_intra):
            raise RuntimeError(
                "initِ PaddleOcrBridge ناموفق بود (SDKِ رسمی/APK)")
        # سلف‌تستِ دسترسپذیری: کراپِ ریزِ سفید → باید سطرِ META برگردد؛
        # شکستِ یک‌باره = خطایِ صریح (فالبکی نیست — ML Kit حذف شده).
        try:
            _img = np.full((64, 64, 3), 255, dtype=np.uint8)
            _ok, _buf = cv2.imencode(".png", _img)
            _out = self._bridge.recognizeAuto(
                bytes(_buf.tobytes()), self.lang, 1, 1)
            if not _out or not str(_out[0]).startswith("META"):
                raise RuntimeError("خروجیِ سلف‌تستِ پدلِ اندروید نامعتبر است")
        except RuntimeError:
            raise
        except Exception as e:
            raise RuntimeError(
                "سلف‌تستِ پلِ پدلِ اندروید مردود شد: "
                + str(e)[:90])
        print(f"[+] OCR گوشی: پدلِ رسمیِ اندروید آماده | SDKِ رسمیِ "
              f"ppocr-android | det=PP-OCRv6_small rec=PP-OCRv6_small "
              f"(باندلِ APK) | threads={_intra}")

    def ocr(self, image_bgr, crop_mode: bool = False):
        """هم‌امضایِ RapidOcrMobile — خروجیِ [ [[box,(t,s)],...] ]."""
        if image_bgr is None or getattr(image_bgr, "size", 0) == 0:
            return None
        _t0 = time.time()
        try:
            _ok, _buf = cv2.imencode(
                ".png", np.ascontiguousarray(image_bgr))
            if not _ok:
                return None
            out = self._bridge.recognizeAuto(
                bytes(_buf.tobytes()), self.lang, 1, 1)
        except Exception as e:
            print(f"[!] خطایِ پدلِ اندروید: {str(e)[:140]}")
            return None
        if not out:
            _pad_stats_note(_t0, 0)
            return None
        lines = []
        for item in out:
            s = str(item)
            if s.startswith("META"):
                continue
            parts = s.split("|", 4)
            if len(parts) < 5:
                continue
            try:
                conf = float(parts[1])
            except Exception:
                conf = 1.0
            txt = parts[3].strip()
            if not txt or conf < 0.25:
                continue
            try:
                nums = [float(v) for v in parts[2].split(",")]
                if len(nums) != 8:
                    continue
                box = np.asarray(nums, dtype=np.float32).reshape(4, 2)
            except Exception:
                continue
            lines.append([box, (txt, float(conf))])
        _pad_stats_note(_t0, len(lines))
        return [lines] if lines else None


def _k3_boost_crop(crop_bgr: np.ndarray):
    """گامِ «افزایشِ کیفیتِ کراپ»ٔ K3: پدِ سفید دورِ کراپ (متنِ چسبیده به
    لبه — مثلِ img6 «You're the real attraction here.» که رویِ لبهٔ چپِ
    صفحه است) + بزرگنماییِ کراپهایِ ریز تا موتورِ استخراج بهتر بخواند.
    خروجی: (کراپِ تقویتشده، pad، scale) برایِ برگرداندنِ مختصات."""
    try:
        h, w = crop_bgr.shape[:2]
    except Exception:
        return crop_bgr, 0, 1.0
    pad = 12
    scale = 1.0
    m = min(h, w)
    if m < 96:
        scale = 3.0
    elif max(h, w) < 480:
        scale = 2.0
    out = cv2.copyMakeBorder(crop_bgr, pad, pad, pad, pad,
                             cv2.BORDER_CONSTANT, value=(255, 255, 255))
    if scale > 1.01:
        out = cv2.resize(out, None, fx=scale, fy=scale,
                         interpolation=cv2.INTER_CUBIC)
    return out, pad, scale


def _k3_map_boxes(lines, pad: float, scale: float):
    """باکسهایِ کراپِ تقویتشده → مختصاتِ کراپِ اصلی."""
    out = []
    if pad == 0 and scale == 1.0:
        return lines
    for box, pair in (lines or []):
        try:
            b = np.asarray(box, dtype=np.float32).reshape(-1, 2)
            b = (b - float(pad)) / float(scale)
            out.append([b.astype(np.float32), pair])
        except Exception:
            continue
    return out


_K3_STATS = {"n": 0, "ms": 0.0, "st1": 0, "st2": 0, "st3": 0}


def _k3_stats_note(t0: float, stage: int) -> None:
    try:
        _K3_STATS["n"] += 1
        _K3_STATS["ms"] += (time.time() - t0) * 1000.0
        _K3_STATS[f"st{stage}"] += 1
        if _K3_STATS["n"] % 20 == 0:
            n = _K3_STATS["n"]
            print(f"[⚡] پدلِ اندروید (نردبانِ K3): {n} کراپ | "
                  f"رسمی={_K3_STATS['st1']} | "
                  f"میانگینِ {_K3_STATS['ms'] / max(1, n):.0f}ms")
    except Exception:
        pass


class K3LadderOCR:
    """v1.14.184 — استخراجِ کراپ با SDKِ رسمیِ PaddleOCR اندروید.

    دستورِ سازنده: «هرروشی تو و گوشی واسه استخراج شده حذف کن فقط از
    همین لینک بالا استفاده کنه» (paddleocr.ai …/android_deployment.html)
    → نردبانِ چندپلهای (پدلِ ONNXِ medium / رپیدِ small / فلاتر-پدلِ
    tiny و مقایسههایِ پوشش/اطمینان) کامل حذف شد. فقط:
      کراپِ detector-v4-s → تقویت (پد + بزرگنماییِ ریزها) →
      SDKِ رسمی (det+rec رویِ همان کراپ — PP-OCRv6_smallِ باندل) →
      برگرداندنِ مختصات. هیچ پاسِ تمامصفحهای نیست (بهجز مسیرِ جانبیِ
      قدیمیِ crop_mode=False) و هیچ فالبکی وجود ندارد (خالی = خالی)."""

    # v1.14.184 — تنها روشِ استخراجِ گوشی = SDKِ رسمیِ PaddleOCR اندروید
    # (دستورِ سازنده: «هرروشی تو گوشی واسه استخراج شده حذف کن فقط از
    # همین لینک بالا استفاده کنه»). مقدارهایِ کهنهٔ MANGA_K3_MODE
    # (full/fast/rapid/paddle/flutter/mlkit/…) همگی نادیده گرفته میشوند.
    _K3_MODES = ("padandroid",)

    def __init__(self, lang: str, build_onnx=None, build_pad=None):
        # v1.14.184 — build_onnx دیگر «هرگز» صدا زده نمیشود (هیچ موتورِ
        # ONNXِ دیگری رویِ گوشی وجود ندارد؛ پارامتر فقط برایِ سازگاریِ
        # امضایِ قدیمی نگاه داشته شده). فقط build_pad = SDKِ رسمی.
        self._lang = lang
        self._build_onnx = None
        self._build_pad = build_pad    # callable() → SDKِ رسمیِ ppocr-android
        self._pad = None
        self._pad_tried = False
        # v1.14.184 — هر مقدارِ کهنه (full/fast/rapid/paddle/flutter/
        # mlkit/…) نادیده گرفته میشود؛ تنها روش = «padandroid».
        self._mode = "padandroid"

    def _engine_pad(self):
        """v1.14.182 — موتورِ «پدلِ رسمیِ اندروید» با کشِ خودش.
        هر خطا/نبودِ پل → None (کراپِ بدونِ موتور = خروجیِ خالی)."""
        if self._pad_tried:
            return self._pad
        self._pad_tried = True
        if self._build_pad is None:
            return None
        try:
            self._pad = self._build_pad()
        except Exception as e:
            print(f"[!] پدلِ رسمیِ اندروید آماده نشد: {str(e)[:110]}")
            self._pad = None
        return self._pad

    def ocr(self, image_bgr: np.ndarray, crop_mode: bool = False):
        if image_bgr is None or getattr(image_bgr, "size", 0) == 0:
            return None
        _t0 = time.time()
        # مسیرِ تمامصفحه (مسیرهایِ جانبیِ قدیمی) → SDKِ رسمی؛ استخراجِ
        # اصلی فقط رویِ کراپ است (دستورِ K3: «نه رو تمام صفحه»).
        if not crop_mode:
            eng0 = self._engine_pad()
            if eng0 is None:
                _k3_stats_note(_t0, 1)
                return None
            try:
                return eng0.ocr(image_bgr)
            except Exception as e:
                print(f"[!] پدلِ رسمیِ اندروید خطا داد: {str(e)[:110]}")
                _k3_stats_note(_t0, 1)
                return None

        # ── SDKِ رسمی رویِ کراپِ تقویتشده (تنها پله؛ بدونِ پلههایِ ۲/۳) ──
        eng0 = self._engine_pad()
        if eng0 is None:
            _k3_stats_note(_t0, 1)
            return None
        try:
            boosted, pad, scale = _k3_boost_crop(image_bgr)
            r0 = eng0.ocr(boosted)
            lines1 = _k3_map_boxes(r0[0], pad, scale) \
                if r0 and r0[0] else []
        except Exception as e:
            print(f"[!] پدلِ رسمیِ اندروید خطا داد: {str(e)[:110]}")
            lines1 = []
        _k3_stats_note(_t0, 1)
        return [lines1] if lines1 else None


# ── v1.14.184 — انتخابِ موتورِ OCRِ گوشی ─────────────────────────────
#   تنها روش = «پدلِ رسمیِ اندروید» (SDKِ رسمیِ ppocr-android با
#   PP-OCRv6_smallِ باندل در assetsِ APK) — MANGA_ANDROID_OCR /
#   MANGA_MOBILE_OCR_ENGINE و مقدارهایِ کهنهٔ MANGA_K3_MODE همگی
#   نادیده گرفته میشوند (دستورِ سازنده: «فقط از همین لینک بالا
#   استفاده کنه»).
# ── v1.14.176 — «آزمایشگاهِ سرعتِ استخراج» ────────────────────────────
# تنظیمها از پنلِ اپ میآیند → bridge آنها را به speed_lab_env() میدهد →
# envهایِ مانده ست/پاک میشوند. پیشفرضِ هر کلید = رفتارِ همین نسخه.

_SPEED_LAB_EP = ("auto",)
# v1.14.184 — SDKِ رسمی رویِ CPU اجرا میشود؛ EPهایِ ONNXِ قدیمی
# (nnapi/xnnpack/cpu) دیگر معنا ندارند. روشِ یگانه = padandroid.
_SPEED_LAB_LADDER = ("padandroid",)

# اسمِ فارسیِ هر روش برایِ لاگها (کلیدِ انگلیسی هم کنارش میآید تا لاگ
# قابلِ جستجو بماند)
_K3_MODE_FA = {
    "padandroid": "پدلِ رسمیِ اندروید",
}

# v1.14.181 — پاکسازیِ یکبارِ مصرفِ مدلهایِ ONNXِ بازنده از گوشی.
# دستورِ سازنده: «بقیش حذف کن تو گوشی استفاده نکنه». v1.14.183 —
# ML Kit هم کلاً حذف شد (دستور: «ml kit حذف کن خوب نیست»). v1.14.184 —
# مدلهایِ medium هم بازنده شدند: استخراج = SDKِ رسمیِ ppocr-android
# با PP-OCRv6_smallِ باندلشده در APK (هیچ مدلِ OCRی دانلود نمیشود).
# سه مجموعهٔ مدلِ بازنده از پوشهٔ rapidocr_modelsِ گوشی حذف میشوند:
#   رپید (small): PP-OCRv6_det_small[.int8]/rec_small + cls + ja/ko
#   پدل (K3 medium): PP-OCRv6_medium_det/rec + korean v5 + ch v4
#   فلاتر-پدل (tiny): PP-OCRv6_tiny_det/rec + dictِ tiny
# فهرستِ نامها از خودِ _RAPIDOCR_FILES میآید (بدونِ تغییرِ آن dict —
# PC از همان helper برایِ مجموعهٔ سبکِ خودش استفاده میکند و بیت‌به‌بیت
# دستنخورده میماند) + نوعِ int8ِ detِ رپید.
_K3_PURGE_EXTRA = ("PP-OCRv6_det_small.int8.onnx",)
_PURGE_MARKER = ".onnx_loser_models_purged_184"


def _purge_loser_onnx_models() -> str:
    """v1.14.181 — حذفِ یکبارِ مدلهایِ ONNXِ بازنده از گوشی.

    فقط اندروید (گیتِ MANGA_PURGE_ONNX_MODELS) — PC بیت‌به‌بیت
    دستنخورده (پوشهٔ هم‌نام رویِ PC مدلهایِ موتورِ خودش را دارد و
    rapidocr از همان میخواند). یکبارمصرف با فایلِ مارکر: اگر مسیرِ
    فالبکِ ONNX (مثلاً APKِ خیلی قدیمی بدونِ پلِ ML Kit) بعداً مدلی
    بخواهد، همان موقع دانلود میشود و پاکِ دوباره نمیشود. خروجی = خطِ
    لاگِ «چه چیزی آزاد شد» یا ""."""
    try:
        if not _android_gate("MANGA_PURGE_ONNX_MODELS"):
            return ""
        _mdir = os.path.join(
            os.environ.get("MANGA_FILES_DIR") or os.getcwd(),
            "rapidocr_models")
        if not os.path.isdir(_mdir):
            return ""
        _mk = os.path.join(_mdir, _PURGE_MARKER)
        if os.path.isfile(_mk):
            return ""
        _names = set(_RAPIDOCR_FILES) | set(_K3_PURGE_EXTRA)
        # v1.14.184 — مدلهایِ medium (~132MB) هم بازندهاند: موتورِ
        # گوشی = SDKِ رسمی با PP-OCRv6_smallِ باندل در APK — هیچ فایلِ
        # مدلی در rapidocr_models نگه داشته نمیشود.
        _keep = ()
        _freed = 0
        _n = 0
        for _fn in sorted(os.listdir(_mdir)):
            _fp = os.path.join(_mdir, _fn)
            if not os.path.isfile(_fp):
                continue
            if _fn in _keep:
                continue
            if _fn in _names or _fn.endswith(".part"):
                try:
                    _freed += os.path.getsize(_fp)
                    os.remove(_fp)
                    _n += 1
                except Exception:
                    pass
        try:
            with open(_mk, "w", encoding="utf-8") as _f:
                _f.write("purged at %s (APP_VER %s)\n"
                         % (time.strftime("%Y-%m-%d %H:%M"), APP_VER))
        except Exception:
            pass
        if _n:
            print("[🧹] v1.14.181 — %d فایلِ مدلِ بازنده (%s) از گوشی حذف شد"
                  % (_n, _fmt_mb(_freed)))
            return ("مدلهایِ بازنده حذف شد: %d فایل / %s آزاد شد — "
                    "روشِ فعالِ v1.14.184 = SDKِ رسمیِ PaddleOCR اندروید"
                    % (_n, _fmt_mb(_freed)))
        return ""
    except Exception:
        return ""


def speed_lab_env(p: dict) -> str:
    """v1.14.184 — روشِ استخراجِ گوشی = SDKِ رسمیِ PaddleOCR اندروید
    (ppocr-android با PP-OCRv6_smallِ باندل).

    تاریخچه: 1.14.176 سوییچهایِ پنل؛ 1.14.178 دکمهٔ «تستِ سرعت»؛
    1.14.181 forceِ برنده + پاکسازیِ مدلهایِ بازنده؛ 1.14.182/183 پدلِ
    رسمیِ اندروید و حذفِ ML Kit؛ 1.14.184 — دستورِ سازنده: «هرروشی تو
    گوشی واسه استخراج شده حذف کن فقط از همین لینک بالا استفاده کنه» →
    تنها روش = SDKِ رسمی؛ پارامترِ p خوانده نمیشود (سازگاریِ امضا با
    bridge)."""
    try:
        # کلیدهایِ قدیمیِ سوییچها هرگز از این نسخه ست نمیشوند — پاککاری
        # برایِ اینکه envِ ماندهٔ پروسههایِ قدیمی اثر نگذارد.
        for _k in ("MANGA_OCR_THREADS", "MANGA_XNN_THREADS",
                   "MANGA_CROP_DET_CAP", "MANGA_CROP_ENH_SCALE"):
            os.environ.pop(_k, None)

        # v1.14.184 — SDKِ رسمی رویِ CPU اجرا میشود؛ هر EPِ کهنه پاک
        # میشود و روشِ فعال همیشه «padandroid» است.
        os.environ.pop("MANGA_MOBILE_OCR_EP", None)
        _w = speed_test_load()
        _lad = "padandroid"
        os.environ["MANGA_K3_MODE"] = "padandroid"
        _ms_l = ""
        try:
            _lm = (_w or {}).get("ladder_ms") or {}
            if _lm.get(_lad):
                _ms_l = " (%.0fms/کراپ — تستِ %s)" % (float(_lm[_lad]),
                                                    str((_w or {}).get("ts") or "?"))
        except Exception:
            _ms_l = ""

        # v1.14.181 — پاکسازیِ یکبارِ مدلهایِ ONNXِ بازنده از گوشی
        _purge = _purge_loser_onnx_models()

        # سنجههایِ سرعت = مالِ «این اجرا» — بینِ کارها ریست
        for _k in ("n", "ms", "st1", "st2", "st3"):
            _K3_STATS[_k] = 0 if _k != "ms" else 0.0
        for _k in ("ms", "n", "lines"):
            _PAD_STATS[_k] = 0 if _k != "ms" else 0.0

        if _purge:
            return ("[⚡] روشِ استخراج: SDKِ رسمیِ PaddleOCR اندروید — "
                    "PP-OCRv6_smallِ باندل (%s)%s | v1.14.184: %s"
                    % (_K3_MODE_FA.get(_lad, _lad), _ms_l, _purge))
        return ("[⚡] روشِ استخراج: SDKِ رسمیِ PaddleOCR اندروید — "
                "PP-OCRv6_smallِ باندل (deploy/ppocr-android — "
                "v1.14.184)%s"
                % (_ms_l,))
    except Exception:
        return ""


# ── v1.14.178 — «تستِ سرعت»: یک دکمه، همهٔ حالتها ───────────────────
# دستورِ سازنده پس از دو باگِ زنجیرهٔ پنل (176/177): «حذفش کن — یک
# دکمه بذار، فعال کردم همه حالت تست کنه، تایم بگیره یک دقیقه
# هرکدومشون، بعد ببینم کدومش سریعه». پس: نه سوییچ، نه انتقالِ تنظیم
# از پنل — خودِ موتور همهٔ حالتها را رویِ کراپهایِ واقعیِ همین تصویر
# اندازه میگیرد (هر حالت یک پنجرهٔ ۶۰ ثانیهای) و برنده را در
# speed_test.json ذخیره میکند؛ speed_lab_env از همان فایل هر کار را
# تنظیم میکند. پروبِ ۱۸۰ ثانیهایِ epprobe هم عملاً بازنشسته میشود:
# پنجرهٔ واقعیِ ۶۰ ثانیهای خودش سنجهٔ سالم/کرش را میدهد.

_SPEED_TEST_FILE = "speed_test.json"


def _speed_test_path() -> str:
    return os.path.join(os.environ.get("MANGA_FILES_DIR") or os.getcwd(),
                        _SPEED_TEST_FILE)


def speed_test_load():
    """نتیجهٔ ذخیرهشدهٔ «تستِ سرعت» — dict یا None."""
    try:
        with open(_speed_test_path(), "r", encoding="utf-8") as _f:
            _d = json.loads(_f.read() or "{}")
        if isinstance(_d, dict) and str(_d.get("ladder") or ""):
            return _d
    except Exception:
        pass
    return None


def _speed_test_save(d: dict) -> None:
    try:
        with open(_speed_test_path(), "w", encoding="utf-8") as _f:
            json.dump(d, _f, ensure_ascii=False, indent=2)
    except Exception as _e:
        print(f"[!] ذخیرهٔ نتیجهٔ «تستِ سرعت» ناموفق: {str(_e)[:120]}")


def _speed_test_pool(page, det0, cap: int = 24):
    """کراپهایِ واقعیِ متن از پاسِ تشخیصِ کاملصفحه — بزرگترینها تا
    سقفِ cap. خروجی = لیستِ آرایههایِ BGR."""
    try:
        _boxes = []
        for _item in (det0 or []):
            try:
                if not (isinstance(_item, (list, tuple)) and _item):
                    continue
                _b = np.asarray(_item[0], dtype=np.float32).reshape(-1, 2)
                _x, _y, _w, _h = cv2.boundingRect(_b.astype(np.int32))
                if _w < 8 or _h < 8:
                    continue
                _boxes.append((_w * _h, _x, _y, _w, _h))
            except Exception:
                continue
        if not _boxes:
            return []
        _boxes.sort(key=lambda t: -t[0])
        _H, _W = page.shape[:2]
        _out = []
        for _a, _x, _y, _w, _h in _boxes[:cap]:
            _x0, _y0 = max(0, _x), max(0, _y)
            _x1, _y1 = min(_W, _x + _w), min(_H, _y + _h)
            if _x1 - _x0 < 8 or _y1 - _y0 < 8:
                continue
            _out.append(page[_y0:_y1, _x0:_x1].copy())
        return _out
    except Exception:
        return []


def _speed_test_tiles(page, cap: int = 24):
    """v1.14.179 — کراپهایِ جایگزین: وقتی تشخیصِ تمامصفحه چیزی نداد
    (لاگِ 178: «در تصویر متنِ خواندنی پیدا نشد» → کلِ تست قطع شد و فقط
    یک حالت «تست» شده بود)، صفحه به کاشیهایِ واقعی (~512px) بریده
    میشود تا تستِ سرعت هیچوقت بنبست پیدا نکند و همهٔ روشها همیشه
    اندازهگیری شوند. هر کاشی پیکسلِ واقعیِ همان صفحه است — هدفِ این
    آزمون فقط سنجشِ سرعت است، نه دقت."""
    try:
        _H, _W = page.shape[:2]
        if not _H or not _W:
            return []
        _side = 512.0
        _ny = max(1, min(6, int(round(_H / _side)) or 1))
        _nx = max(1, min(6, int(round(_W / _side)) or 1))
        while _nx * _ny > cap:
            if _nx >= _ny and _nx > 1:
                _nx -= 1
            elif _ny > 1:
                _ny -= 1
            else:
                break
        _out = []
        for _iy in range(_ny):
            for _ix in range(_nx):
                _y0, _y1 = (_H * _iy) // _ny, (_H * (_iy + 1)) // _ny
                _x0, _x1 = (_W * _ix) // _nx, (_W * (_ix + 1)) // _nx
                if _y1 - _y0 < 64 or _x1 - _x0 < 64:
                    continue
                _out.append(page[_y0:_y1, _x0:_x1].copy())
        return _out[:cap]
    except Exception:
        return []


def _speed_test_window(runner, pool, per_mode, should_stop=None):
    """یک پنجرهٔ زمانی رویِ pool: کراپِ اول = گرمکردنِ مدلها (بیرونِ
    سنجه)؛ بعد تا پرشدنِ پنجره کراپها لوپ میشود. خروجی =
    (تعداد، مجموعِ ثانیهٔ خالص، خطا، متوقفشده)."""
    _n, _tsum, _err = 0, 0.0, None
    try:
        runner(pool[0])  # گرمکردن — ساختنِ سشن/مدل در سنجه نمیآید
    except Exception as _e:
        return 0, 0.0, str(_e), False
    _t0 = time.time()
    _stopped = False
    while (time.time() - _t0) < per_mode:
        for _crop in pool:
            if should_stop is not None and should_stop():
                _stopped = True
                break
            _t1 = time.time()
            try:
                runner(_crop)
            except Exception as _e:
                _err = str(_e)
                break
            _tsum += time.time() - _t1
            _n += 1
            if (time.time() - _t0) >= per_mode:
                break
        if _err or _stopped:
            break
    return _n, _tsum, _err, _stopped


def speed_test_run(src, langs=("en",), per_mode=60.0, log=print,
                   should_stop=None, backend=None):
    """«تستِ سرعتِ استخراج» — یک پنجره رویِ روشِ یگانهٔ v1.14.184.

    ۱) تصویر ورودی باز میشود؛ SDKِ رسمیِ PaddleOCR یک پاسِ تشخیصِ
       کاملصفحه میزند و کراپهایِ واقعیِ متن را میدهد (تا ۲۴ کراپ).
       اگر تشخیص چیزی نداد — صفحه به کاشیهایِ واقعیِ (~۵۱۲px) بریده
       میشود؛ تست هیچوقت بنبست پیدا نمیکند (v1.14.179).
    ۲) یک پنجرهٔ روش (padandroid = SDKِ رسمیِ ppocr-android با
       PP-OCRv6_smallِ باندل) رویِ همان کراپها؛ موتورِ واقعی
       اندازهگیری میشود. پنجرههایِ روشها/شتاب‌دهندههایِ قدیمی
       (full/fast/rapid/paddle/flutter + cpu/xnnpack/nnapi) حذف شدند —
       فقط یک روش وجود دارد (دستورِ سازنده: «فقط از همین لینک»).
    ۳) نتیجه در speed_test.json ذخیره میشود (speed_lab_env) — دیگر
       هیچ انتخابی در کار نیست؛ فقط برایِ لاگِ سازنده.
    خروجی: dictِ نتیجه (یا None با پیامِ لاگ). backend فقط برایِ تست
    (تزریقِ فیک) — پیشفرض = RapidOCRBackend واقعی."""
    try:
        per_mode = max(5.0, float(per_mode or 60.0))
    except Exception:
        per_mode = 60.0
    lang = (langs[0] if langs else "en") or "en"
    _modes = tuple(K3LadderOCR._K3_MODES)
    log("[⚡] تستِ سرعتِ استخراج: %d روش (%s) × %d ثانیه"
        % (len(_modes),
           " + ".join(_K3_MODE_FA.get(_m, _m) for _m in _modes),
           int(per_mode)))
    log("[⚡] در این حالت ترجمه انجام نمیشود — فقط استخراجِ متن "
        "اندازهگیری میشود؛ لطفاً برنامه را باز نگه دار…")
    _t_all = time.time()
    try:
        page = MangaTranslator._imread_any(src)
    except Exception as _e:
        log("[!] تصویر ورودی باز نشد: %s" % str(_e)[:140])
        return None
    if page is None or getattr(page, "size", 0) == 0:
        log("[!] تصویر ورودی باز نشد (%s)" % os.path.basename(str(src or "")))
        return None
    try:
        be = backend if backend is not None else RapidOCRBackend(lang=lang)
    except Exception as _e:
        log("[!] موتورِ OCR ساخته نشد: %s" % str(_e)[:140])
        return None
    _lad0 = getattr(be, "_mobile", None)
    if not isinstance(_lad0, K3LadderOCR):
        log("[!] «تستِ سرعت» رویِ نردبانِ K3 کار میکند — این دستگاه "
            "نردبان ندارد (PC/موتورِ دیگر). از اپِ گوشی تست کن.")
        return None

    _prev = speed_test_load() or {}
    _nnapi_pending = bool(_prev.get("nnapi_pending"))

    # v1.14.184 — تنها موتورِ اندازهگیری = SDKِ رسمیِ PaddleOCR اندروید
    try:
        _padbe = be._build_paddle_android(lang)
    except Exception:
        _padbe = None

    # ── استخرِ کراپها: یک پاسِ تشخیصِ کاملصفحه با SDKِ رسمی ──
    log("[⚡] استخرِ کراپهایِ واقعی از تصویر…")
    _res0 = None
    if _padbe is not None:
        try:
            _res0 = _padbe.ocr(page, crop_mode=False)
        except Exception as _e:
            _res0 = None
            log("[!] تشخیصِ تمامصفحه خطا داد: %s" % str(_e)[:140])
    pool = _speed_test_pool(page, _res0)
    if not pool:
        # v1.14.179 — پایانِ بنبستِ ۱۷۸: بهجایِ قطعِ کلِ تست (لاگ:
        # «در تصویر متنِ خواندنی پیدا نشد» → فقط یک حالت «تست» شده بود)
        # صفحه به کاشیهایِ واقعیِ خودش بریده میشود؛ همهٔ پنجرهها همیشه
        # پیموده میشوند.
        pool = _speed_test_tiles(page)
        log("[⚡] تشخیصِ تمامصفحه چیزی ندید — با %d کاشیِ واقعیِ خودِ "
            "صفحه ادامه میدهیم؛ همهٔ روشها اندازهگیری میشوند." % len(pool))
    if not pool:
        log("[!] تصویر خیلی ریز/خالی است — یک صفحهٔ بزرگتر امتحان کن.")
        return None
    log("[⚡] %d کراپِ آماده — پنجرهها شروع میشوند…" % len(pool))

    _res = {"app": APP_VER,
            "ts": time.strftime("%Y-%m-%d %H:%M"),
            "per_mode": int(per_mode), "crops": len(pool),
            "ladder": str(_prev.get("ladder") or "full"),
            "ep": str(_prev.get("ep") or "auto"),
            "ladder_ms": {}, "ep_ms": {},
            "ladder_n": {}, "ep_n": {},
            "nnapi_pending": False}
    _total = len(_modes)
    _wi = 0

    # ── پنجرههایِ روشِ استخراج ──
    for _mode in _modes:
        _wi += 1
        _need_ok = {"padandroid": _padbe is not None}[_mode]
        if not _need_ok:
            _res["ladder_ms"][_mode] = None
            log("[⚡] (%d/%d) روشِ %s (%s) → رد شد (موتورش رویِ این دستگاه آماده نیست)"
                % (_wi, _total, _K3_MODE_FA.get(_mode, _mode), _mode))
            continue
        os.environ["MANGA_K3_MODE"] = _mode
        try:
            _lad = K3LadderOCR(lang, build_pad=lambda: _padbe)
        except Exception as _e:
            _res["ladder_ms"][_mode] = None
            log("[⚡] (%d/%d) روشِ %s (%s) → نردبان ساخته نشد: %s"
                % (_wi, _total, _K3_MODE_FA.get(_mode, _mode), _mode,
                   str(_e)[:100]))
            continue
        _n, _ts, _err, _stp = _speed_test_window(
            lambda c, _l=_lad: _l.ocr(c, crop_mode=True),
            pool, per_mode, should_stop=should_stop)
        _ms = (_ts * 1000.0 / _n) if _n else None
        _res["ladder_ms"][_mode] = _ms
        _res["ladder_n"][_mode] = _n
        if _err:
            log("[⚡] (%d/%d) روشِ %s (%s) → خطا: %s"
                % (_wi, _total, _K3_MODE_FA.get(_mode, _mode), _mode,
                   str(_err)[:100]))
        elif _stp:
            log("[⚡] (%d/%d) روشِ %s (%s) → متوقف شد (%d کراپ)"
                % (_wi, _total, _K3_MODE_FA.get(_mode, _mode), _mode, _n))
            _speed_test_save(_res)
            return _res
        else:
            log("[⚡] (%d/%d) روشِ %s (%s) → %d کراپ | میانگینِ %.0fms/کراپ"
                % (_wi, _total, _K3_MODE_FA.get(_mode, _mode), _mode,
                   _n, _ms))
        _speed_test_save(_res)  # بعد از هر پنجره ذخیره — کرش = از دست نمیرود

    # ── v1.14.184 — پنجرههایِ شتاب‌دهنده حذف شدند: SDKِ رسمی رویِ CPU ──

    # ── برندهها + جدولها ──
    _ok_l = {k: v for k, v in _res["ladder_ms"].items() if v}
    _ok_e = {k: v for k, v in _res["ep_ms"].items() if v}
    if not _ok_l and not _ok_e:
        log("[!] هیچ پنجرهٔ سالمی تمام نشد — نتیجه‌ای ذخیره نشد.")
        return None
    _best_l = min(_ok_l, key=_ok_l.get) if _ok_l else \
        str(_prev.get("ladder") or "full")
    _best_e = min(_ok_e, key=_ok_e.get) if _ok_e else \
        str(_prev.get("ep") or "auto")
    _res["ladder"], _res["ep"] = _best_l, _best_e
    _res["seconds"] = int(time.time() - _t_all)
    _speed_test_save(_res)
    _tbl = " | ".join("%s(%s)=%.0fms" % (_K3_MODE_FA.get(k, k), k, v)
                      for k, v in sorted(_ok_l.items(), key=lambda kv: kv[1]))
    log("[⚡] جدولِ روشها (سریع → کند): %s" % (_tbl or "—"))
    log("[⚡] شتاب‌دهندهٔ جداگانه ندارد — SDKِ رسمی رویِ CPU با "
        "EngineConfig.numThreads اجرا میشود (v1.14.184).")
    log("[⚡] برنده: روشِ %s (%s؛ %s) → ذخیره شد (v1.14.184: تنها روش — "
        "شتاب‌دهندهٔ جداگانه ندارد)."
        % (_K3_MODE_FA.get(_best_l, _best_l), _best_l,
           ("%.0fms/کراپ" % _ok_l[_best_l]) if _best_l in _ok_l else "—"))
    try:
        log("[⚡] کلِ تست: %d دقیقه و %d ثانیه"
            % (_res["seconds"] // 60, _res["seconds"] % 60))
    except Exception:
        pass
    return _res


def _k3_speed_report() -> str:
    """گزارشِ سرعتِ «این اجرا» — bridge بعد از پایانِ هر کار لاگش میکند
    تا سازنده بتونه بینِ حالتهایِ آزمایشگاه مقایسه کنه."""
    try:
        _n = int(_K3_STATS.get("n") or 0)
        if _n <= 0:
            return ""
        _ms = float(_K3_STATS.get("ms") or 0.0)
        _out = ("[🧪] گزارشِ سرعتِ استخراج: %d کراپ | میانگینِ %.0fms | "
                "رسمی=%d"
                % (_n, _ms / max(1, _n), int(_K3_STATS.get("st1") or 0)))
        try:
            _pn = int(_PAD_STATS.get("n") or 0)
            if _pn > 0:
                _out += (" | پدلِ رسمیِ تنهایی: میانگینِ %.0fms"
                         % (float(_PAD_STATS.get("ms") or 0.0) / _pn))
        except Exception:
            pass
        try:
            _lad = str(os.environ.get("MANGA_K3_MODE", "") or "").strip().lower()
            _out += " | روش=%s" % (_lad if _lad else "padandroid")
        except Exception:
            pass
        return _out
    except Exception:
        return ""


class RapidOCRBackend:

    def __init__(self, lang: str = "en", prefer_gpu: Optional[bool] = None):
        self.lang = lang
        self._new_api = False
        self._mobile = None
        # v1.14.154 — گاردِ CJK برایِ زبانِ لاتین (اندروید؛ PC بدونِ گیت
        # همیشه خاموش — رفتارِ PC بیت‌به‌بیت)
        try:
            self._cjk_guard = _android_gate("MANGA_CJK_GUARD") and \
                str(lang).lower() in ("en", "latin", "english")
        except Exception:
            self._cjk_guard = False
        # v1.14.123 — اندروید: موتورِ PP-OCRv6 ONNX (عینِ PC/K3) از
        # rapidocr_mobile (بدونِ پکیجِ rapidocr/pyclipper/shapely).
        # زمینه: دیکدِ K3 v4.1.1 نشان داد K3 رویِ گوشی هم همین پایپلاینِ
        # ONNX را اجرا میکند (RunRapidOcrPipelineOnCrop + _ppOcrDict +
        # ppocrv6_dict.txt) و دقیق/سریع استخراج میزند. درخواستِ کاربر:
        # «استخراجِ مالِ پی‌سی لینوکس هستو رو گوشی اوکی کرد».
        if _IS_ANDROID:
            self._init_mobile_engine(lang)
            return
        # v1.14.96-speed — prefer_gpu از MangaTranslator.use_gpu می‌آید
        # (همان تصمیمِ auto/--cpuِ OCR). None = رفتارِ قبل (فقط CPU).
        self._prefer_gpu = prefer_gpu
        try:
            # v1.14.29: rapidocr فقط همین‌جا (وقتی موتور ONNX واقعاً لازم است) نصب می‌شود
            if not _ensure_rapidocr_pkg():
                raise ImportError("rapidocr نصب نیست و نصب خودکار ناموفق بود")
            from rapidocr import RapidOCR as NewRapidOCR
            # v1.14.95 — سکوتِ لاگِ RapidOCR: هر کراپِ خالی یک خطِ
            # [WARNING] «The text detection result is empty» می‌نوشت و
            # کنسول/وب را پر می‌کرد (شکایتِ «لاگِ اضافه» کاربر).
            # نکته: موتور در init خودش level را INFO می‌کند → setLevel
            # کافی نیست؛ «فیلتر» رویِ همان لاگر ماندگار است.
            try:
                import logging as _lg

                class _QuietRapidOCR(_lg.Filter):
                    def filter(self, rec):
                        return rec.levelno >= _lg.ERROR

                for _ln in ("RapidOCR", "rapidocr"):
                    _lg.getLogger(_ln).addFilter(_QuietRapidOCR())
                    _lg.getLogger(_ln).propagate = False
            except Exception:
                pass
            _low = str(lang).lower()
            _rec_params = None
            if _low in ("korean", "ko"):
                try:
                    from rapidocr import OCRVersion as _OV, ModelType as _MT, LangRec as _LR
                    _rec_params = {
                        "Rec.lang_type": getattr(_LR, "KOREAN", _LR.KOREAN),
                        "Rec.ocr_version": _OV.PPOCRV5,
                        "Rec.model_type": _MT.MOBILE,
                    }
                except Exception as e:
                    print(f"[!] پیکربندی مدل کره‌ای RapidOCR نشد ({e}) → مدل پیش‌فرض")
            elif _low in ("japan", "ja", "japanese"):
                try:
                    from rapidocr import OCRVersion as _OV, ModelType as _MT, LangRec as _LR
                    _japan = getattr(_LR, "JAPAN", None)
                    if _japan is not None:
                        _rec_params = {
                            "Rec.lang_type": _japan,
                            "Rec.ocr_version": _OV.PPOCRV4,
                            "Rec.model_type": _MT.MOBILE,
                        }
                    else:
                        print("[!] LangRec.JAPAN در rapidocr نیست → مدل پیش‌فرض")
                except Exception as e:
                    print(f"[!] پیکربندی مدل ژاپنی RapidOCR نشد ({e}) → مدل پیش‌فرض")
            import os as _os
            _mdir = _os.path.join(
                _os.environ.get("MANGA_FILES_DIR") or _os.getcwd(),
                "rapidocr_models")
            try:
                _os.makedirs(_mdir, exist_ok=True)
            except Exception:
                _mdir = None
            _base = {"Global.model_root_dir": _mdir} if _mdir else {}
            if _mdir:
                try:
                    # v1.14.29: فقط مدل‌های همین زبان دانلود می‌شود — نه همهٔ زبان‌ها
                    # (det مشترک است؛ rec مخصوص زبان؛ cls دیگر استفاده نمی‌شود)
                    # v1.14.152 — مجموعهٔ K3 با helperِ مشترک
                    _det_n52, _rec_n52 = _rapidocr_model_pair(lang, small=True)  # v1.14.154 — PC = مجموعهٔ سبکِ قبلی (دستنخورده)
                    _ensure_rapidocr_models(_mdir,
                                            files=[_det_n52, _rec_n52])
                except Exception as _e:
                    print(f"[!] پیش‌دانلود مدل‌ها ناموفق: {_e}")
            # v1.14.96-speed — مدل‌هایِ det/rec (و cls اگر فایلش موجود باشد)
            # «صریحاً» از فایل‌هایِ دانلودشدهٔ ریلیزِ «models» (GitHub) به
            # موتور داده می‌شوند: rapidocr دیگر خودش دانلود/بررسیِ SHA از
            # modelscope انجام نمی‌دهد و دقیقاً همان فایلِ کش‌شده (که از
            # ریلیزِ models آمده) استفاده می‌شود. فایل نبود؟ → همان رفتارِ
            # قبل: rapidocr خودش برمی‌دارد (model_root_dir).
            _gpu_flags69 = {}
            if _mdir:
                try:
                    # v1.14.152 — مسیرِ صریحِ مدلها از helperِ مجموعهٔ K3
                    _det_n52, _rec_n52 = _rapidocr_model_pair(lang, small=True)  # v1.14.154 — PC = مجموعهٔ سبکِ قبلی (دستنخورده)
                    for _sec69, _fn69 in (
                            ("Det", _det_n52),
                            ("Rec", _rec_n52),
                            ("Cls", "ch_ppocr_mobile_v2.0_cls_mobile.onnx")):
                        _mp69 = _os.path.join(_mdir, _fn69)
                        if _os.path.isfile(_mp69) \
                                and _os.path.getsize(_mp69) > 100_000:
                            _base[f"{_sec69}.model_path"] = _mp69
                    # v1.14.152 — مدلهایِ رسمیِ PaddlePaddle (medium/korean)
                    # dict را داخلِ metadata ندارند → rapidocr بدونِ
                    # rec_keys_path دنبالِ dict_url میگردد و «Missing key
                    # dict_url» میدهد. فایلِ dict محلیِ همان مدل را میدهیم
                    # (ch v4 و japan خودشان dictِ داخلی دارند — دست نمیخورند).
                    if _rec_n52 in ("PP-OCRv6_medium_rec_onnx.onnx",
                                    "PP-OCRv5_korean_rec.onnx"):
                        _keys52 = ("ppocrv6_chars.txt"
                                   if _rec_n52.startswith("PP-OCRv6")
                                   else "korean_chars.txt")
                        try:
                            _ensure_rapidocr_models(_mdir, files=[_keys52])
                        except Exception:
                            pass
                        _kp52 = _os.path.join(_mdir, _keys52)
                        if _os.path.isfile(_kp52) \
                                and _os.path.getsize(_kp52) > 100:
                            _base["Rec.rec_keys_path"] = _kp52
                except Exception as _e69:
                    print(f"[!] مسیرِ صریحِ مدلِ OCR نشد ({_e69}) → auto")
            # v1.14.96-speed — EPِ سشن‌هایِ OCR هم از انتخابگرِ مرکزیِ
            # _best_providers_for: اگر CUDA/Dml/CoreML واقعاً موجود است و
            # --cpu نزده، rapidocr هم رویِ همان EP می‌رود (همان مدلِ
            # PP-OCRv6؛ فقط سریع‌تر). در بیلدِ CPU-only هیچ فرقی با قبل
            # ندارد و ساختِ سشنِ GPU شکست بخورد → بدونِ GPU دوباره ساخته
            # می‌شود (فال‌بکِ امن).
            try:
                _want69 = bool(prefer_gpu) and (_ORT_CUDA_OK is not False)
                _ocr_head69 = (_best_providers_for("ocr", prefer_gpu=_want69)
                               or ["CPUExecutionProvider"])[0]
                if _ocr_head69 == "CUDAExecutionProvider":
                    _gpu_flags69["EngineConfig.onnxruntime.use_cuda"] = True
                    # v1.14.96-speed (SRV-G phase2) — CUDA EP options برایِ
                    # سشن‌هایِ OCR هم (فقط وقتی مسیرِ GPU فعال است تا فال‌بکِ
                    # CPU را آلوده نکند؛ در فال‌بک حذف می‌شود)
                    _gpu_flags69["EngineConfig.onnxruntime.cuda_ep_cfg.cudnn_conv_use_max_workspace"] = "1"
                    # v1.14.98-speed (SRV-H3) — OCR هم MANGA_CUDNN_ALGO را
                    # رعایت کند (سشن‌هایِ det/rec رویِ CUDA بدونِ
                    # EXHAUSTIVE re-search وقتی heuristic خواسته شده)
                    _algo_h3 = _cudnn_algo_search()
                    if _algo_h3:
                        _gpu_flags69["EngineConfig.onnxruntime.cuda_ep_cfg.cudnn_conv_algo_search"] = _algo_h3
                elif _ocr_head69 == "DmlExecutionProvider":
                    _gpu_flags69["EngineConfig.onnxruntime.use_dml"] = True
                elif _ocr_head69 == "CoreMLExecutionProvider":
                    _gpu_flags69["EngineConfig.onnxruntime.use_coreml"] = True
                if _gpu_flags69:
                    _base.update(_gpu_flags69)
                    print(f"[*] EPِ OCR: {_ocr_head69}")
            except Exception:
                _gpu_flags69 = {}
            try:
                import os as _os2
                _cpu_n = _os2.cpu_count() or 4
            except Exception:
                _cpu_n = 4
            # v1.14.66 — MANGA_OCR_THREADS همچنان مقدم است (اگر تنظیم شود).
            # v1.14.99 (SRV-H4) — wiringِ SRV-G (‎-1/emulator=1) خنثی شد و
            # wiringِ e32bccf (PC: cores÷2 تا ۴؛ اندروید: ۱/۲) برگشت —
            # «پیش‌فرضِ خودِ rapidocr» (-1 = ORT auto) همان رگرسیونِ
            # extract را می‌داد. MANGA_ORT_THREADS فقط با تنظیمِ صریح به
            # OCR هم اعمال می‌شود (opt-in tuning).
            try:
                _ocr_th = int(_os2.environ.get("MANGA_OCR_THREADS", "0") or 0)
            except Exception:
                _ocr_th = 0
            try:
                _env_ort_h4 = int(_os2.environ.get("MANGA_ORT_THREADS", "0") or 0)
            except Exception:
                _env_ort_h4 = 0
            _intra = None
            if _ocr_th > 0:
                _intra = max(1, _ocr_th)
            elif _env_ort_h4 > 0:
                _intra = max(1, _env_ort_h4)
            elif _on_android():
                # v1.14.66 — اندروید مثلِ قبل (رم)
                _intra = 1 if _cpu_n <= 4 else 2
            else:
                # v1.14.99 (SRV-H4) — wiringِ e32bccf بازگشت (سقفِ ۲..۴ رویِ
                # PC): پیش‌فرضِ خودِ rapidocr (-1 = ORT auto = همهٔ هسته‌ها)
                # همان رگرسیونِ extract را می‌دهد (SRV-H2) — پروبِ سرور:
                # 27.5s → 20.4s رویِ 01.jpg با ۴ نخ. اوررایدِ صریح
                # (MANGA_OCR_THREADS / MANGA_ORT_THREADS) مقدم است.
                # v1.14.99-speed (SRV-L) — انحرافِ مستندشده: رویِ میزبانِ
                # بزرگِ x86_64 (≥۸ هسته، همان هیوریستیکِ
                # _ort_session_options) پیش‌فرضِ OCR هم ۸ می‌شود — برندهٔ
                # سوییپِ SRV-K (t8: extract 14.9s) با envِ MANGA_ORT_THREADS=8
                # به OCR هم اعمال می‌شد؛ بدونِ این، 01.jpg رویِ سرورِ تازه
                # ~38.8s می‌داد (extract 21.2s با OCR@4) و گیتِ ≤34s
                # رد می‌شد. میزبانِ کوچک/گوشی: همان ۲..۴.
                try:
                    import platform as _pfo
                    if _pfo.machine().lower() in ("x86_64", "amd64") \
                            and (_cpu_n or 4) >= 8:
                        _intra = 8
                    else:
                        _intra = max(2, min(4, _cpu_n // 2))
                except Exception:
                    _intra = max(2, min(4, _cpu_n // 2))
            _threads = {
                "EngineConfig.onnxruntime.intra_op_num_threads": int(_intra),
                "EngineConfig.onnxruntime.inter_op_num_threads": 1,
            }
            _intra_disp = _intra
            if _rec_params is not None:
                _p = dict(_rec_params)
                _p.update(_base)
                _p.update(_threads)
                try:
                    self.engine = NewRapidOCR(params=_p)
                except Exception as _eg69:
                    # v1.14.96-speed — اگر ساختِ سشنِ GPU شکست، بدونِ EPِ GPU
                    # دوباره (تا فال‌بکِ legacyِ PP-OCRv3 فعال نشود)
                    if not _gpu_flags69:
                        raise
                    print(f"[!] EPِ GPU برایِ OCR نشد ({str(_eg69)[:130]}) → CPU")
                    _p2 = {k: v for k, v in _p.items() if k not in _gpu_flags69}
                    self.engine = NewRapidOCR(params=_p2)
                self._new_api = True
                print(f"[+] RapidOCR (ONNX, PP-OCRv5) آماده | lang={lang} | threads={_intra_disp} | cls=خاموش")
                return
            _pb = dict(_base)
            _pb.update(_threads)
            try:
                self.engine = NewRapidOCR(params=_pb)
            except Exception as _eg69:
                if not _gpu_flags69:
                    raise
                print(f"[!] EPِ GPU برایِ OCR نشد ({str(_eg69)[:130]}) → CPU")
                _pb2 = {k: v for k, v in _pb.items() if k not in _gpu_flags69}
                self.engine = NewRapidOCR(params=_pb2)
            self._new_api = True
            print(f"[+] RapidOCR (ONNX, PP-OCRv5/v6) آماده | lang={lang} | threads={_intra_disp} | cls=خاموش")
            return
        except Exception as e:
            import traceback as _tb
            print(f"[!] RapidOCR (API جدید) لود نشد: {e}")
            print("[!] " + _tb.format_exc()[-900:])
        if not _HAS_RAPIDOCR:
            raise ImportError("pip install rapidocr (یا rapidocr-onnxruntime)")
        self.engine = RapidOCR()
        print(f"[+] RapidOCR (ONNX, PP-OCRv3 قدیمی) آماده | lang={lang}")

    def _init_mobile_engine(self, lang: str) -> None:
        """v1.14.184 — موتورِ یگانهٔ استخراجِ گوشی = SDKِ رسمیِ PaddleOCR
        اندروید (ماژولِ رسمیِ ppocr-sdkِ وندورشده — deploy/ppocr-android
        با PP-OCRv6_smallِ باندل در assets).

        دستورِ سازنده: «هرروشی تو و گوشی واسه استخراج شده حذف کن فقط از
        همین لینک بالا استفاده کنه» → همهٔ موتورهایِ دیگر (پدلِ ONNXِ
        medium، رپیدِ small، فلاتر-پدلِ tiny و envهایِ کهنهٔ انتخابِ
        موتور) حذف شدند؛ فالبکی وجود ندارد — خطایِ
        ساختِ موتور = استخراجِ خالیِ صریح (با لاگ). استخراج همچنان فقط
        رویِ کراپهایِ detector-v4-s اجرا میشود (بدونِ پاسِ تمامصفحه)."""
        _pb = self._build_paddle_android(lang)
        if _pb is not None:
            self._mobile = _pb
            return
        print("[!] SDKِ رسمیِ PaddleOCR اندروید آماده نشد — استخراجِ گوشی "
              "خالی میماند (فالبکی نیست — همهٔ روشهایِ دیگر حذف شدند؛ "
              "دستورِ سازنده: «فقط از همین لینک بالا استفاده کنه»)")
        self._mobile = None

    def _build_paddle_android(self, lang: str):
        """v1.14.184 — ساختِ موتورِ «SDKِ رسمیِ PaddleOCR اندروید»
        (ماژولِ رسمیِ ppocr-sdkِ وندورشده از deploy/ppocr-android با
        مدلهایِ رسمیِ PP-OCRv6_smallِ باندل در assets) — دستورِ سازنده:
        «هرروشی تو و گوشی واسه استخراج شده حذف کن فقط از همین لینک بالا
        استفاده کنه». پلِ Kotlin = PaddleOcrBridge (پلِ نازک رویِ
        PaddleOCR.createِ رسمی). هر خطا (APKِ قدیمی/بیلدِ ناقص) → None
        (هیچ فالبکی نیست — همهٔ روشهایِ دیگر حذف شدهاند)."""
        try:
            return PaddleAndroidOCR(lang)
        except Exception as e:
            print(f"[!] پدلِ رسمیِ اندروید آماده نشد: {str(e)[:130]}")
            return None

    @staticmethod
    def _deaccent(txt: str) -> str:
        try:
            import unicodedata as _ud
            out = _ud.normalize("NFKD", txt)
            out = "".join(ch for ch in out if not _ud.combining(ch))
            return out
        except Exception:
            return txt

    def ocr(self, image_bgr: np.ndarray, crop_mode: bool = False):

        if image_bgr is None or image_bgr.size == 0:
            return None
        # v1.14.123 — اندروید: موتورِ PP-OCRv6 ONNX (خروجی هم‌قالبِ
        # مسیرهایِ دیگر: [ [box, (text, score)], ... ])
        # v1.14.125 — crop_mode: detِ برشِ بدونِ بزرگنمایی با سقفِ
        # det_cap (فقط مسیرهایِ برشِ کاسکاد/نجات میفرستند؛ صفحه = False)
        if self._mobile is not None:
            try:
                # v1.14.163 — سبکِ جدید: OCR فقط رویِ کراپِ detector-v4-s
                # صدا زده میشود (crop_mode=True). هیچ باندهای/کاسکادی
                # نیست؛ فراخوانیِ تمامصفحه فقط برای مسیرهایِ قدیمیِ
                # جانبی (detect_text) میماند.
                _out = self._mobile.ocr(image_bgr, crop_mode=crop_mode)
            except Exception as _e164:
                # v1.14.164 — خطایِ بیصدا ممنوع: رگِ «متن پیدا نشد»ٔ
                # 1.14.163 یک AttributeErrorِ بیصدا بود (رگرسیونِ
                # تودرتوییِ _ocr_impl)؛ حالا هر خرابیِ OCR یک خطِ کوتاه
                # و مشخص در لاگ میدهد تا ریشه فوراً دیده شود.
                print(f"[!] خطایِ OCRِ موبایل: {str(_e164)[:150]}")
                return None
            if not _out or not _out[0]:
                return None
            _lines = []
            _ncjk = 0
            for _box, _pair in _out[0]:
                try:
                    _t = self._deaccent(str(_pair[0])).strip()
                    if not _t:
                        continue
                    if self._cjk_guard and _cjk_dominant_154(_t):
                        _ncjk += 1
                        continue
                    _s = float(_pair[1])
                    _lines.append([_box, (_t, _s)])
                except Exception:
                    continue
            if _ncjk:
                print(f"    [OCR] {_ncjk} خطِ پر از نویسهٔ چینی حذف شد "
                      "(گاردِ لاتین — v1.14.154)")
            return [_lines] if _lines else None
        if self._new_api:
            try:
                try:
                    out = self.engine(image_bgr, use_cls=False)
                except TypeError:
                    out = self.engine(image_bgr)
                txts = getattr(out, "txts", None)
                if not txts:
                    return None
                boxes = getattr(out, "boxes", None)
                scores = getattr(out, "scores", None)
                lines = []
                for i, t in enumerate(txts):
                    t = self._deaccent(str(t)).strip()
                    if not t:
                        continue
                    score = float(scores[i]) if scores is not None and i < len(scores) else 1.0
                    box = boxes[i] if boxes is not None and i < len(boxes) else [[0, 0], [1, 0], [1, 1], [0, 1]]
                    lines.append([np.asarray(box, dtype=np.float32), (t, score)])
                return [lines] if lines else None
            except Exception as e:
                msg = str(e).lower()
                if "text detection result is empty" in msg or "detection result is empty" in msg:
                    return None
                print(f"    [OCR] rapidocr جدید خطا: {e} → موتور قدیمی")
                self._new_api = False
                if not _HAS_RAPIDOCR:
                    return None
        try:
            try:
                result, _ = self.engine(image_bgr, use_cls=False)
            except TypeError:
                result, _ = self.engine(image_bgr)
        except Exception as e:
            msg = str(e).lower()
            if "text detection result is empty" in msg or "detection result is empty" in msg:
                return None
            return None
        if not result:
            return None
        lines = []
        for item in result:
            if len(item) < 3:
                continue
            box, text, score = item[0], item[1], item[2]
            text = self._deaccent(str(text)).strip()
            if not text:
                continue
            lines.append([box, (text, float(score))])
        return [lines] if lines else None


